-- Formulas
INSERT OR IGNORE INTO formulas (id, subject_id, slug, name, latex, description, variables, status) VALUES ('frm_5892a145fce398', 'subj_math', 'special-trig-limits', 'Special trigonometric limits', '\lim_{x \to 0} \frac{\sin x}{x} = 1, \qquad \lim_{x \to 0} \frac{1 - \cos x}{x} = 0', 'Two limits proved with the Squeeze Theorem; x is in radians. They give the derivatives of sine and cosine.', '[{"symbol":"x","meaning":"angle in radians"}]', 'published');
INSERT OR IGNORE INTO formulas (id, subject_id, slug, name, latex, description, variables, status) VALUES ('frm_3841cb862eb86a', 'subj_math', 'derivative-rules', 'Sum, product and quotient rules', '(f \pm g)'' = f'' \pm g'', \quad (fg)'' = f''g + fg'', \quad \left(\frac{f}{g}\right)'' = \frac{f''g - fg''}{g^2}', 'Derivatives of sums, products and quotients of differentiable functions (the quotient rule needs g ≠ 0).', '[{"symbol":"f, g","meaning":"differentiable functions of x"}]', 'published');
INSERT OR IGNORE INTO formulas (id, subject_id, slug, name, latex, description, variables, status) VALUES ('frm_45b7fb88cca2f3', 'subj_math', 'chain-rule', 'Chain rule', '\frac{d}{dx} f(g(x)) = f''(g(x))\, g''(x), \qquad \frac{dy}{dx} = \frac{dy}{du}\cdot\frac{du}{dx}', 'The derivative of a composition: the outside derivative evaluated at the inside, times the inside derivative.', '[{"symbol":"g","meaning":"inner function"},{"symbol":"f","meaning":"outer function"}]', 'published');
INSERT OR IGNORE INTO formulas (id, subject_id, slug, name, latex, description, variables, status) VALUES ('frm_8a3aa3fec7718d', 'subj_math', 'trig-derivatives', 'Derivatives of trigonometric functions', '(\sin x)'' = \cos x,\ (\cos x)'' = -\sin x,\ (\tan x)'' = \sec^2 x,\ (\cot x)'' = -\csc^2 x,\ (\sec x)'' = \sec x \tan x,\ (\csc x)'' = -\csc x \cot x', 'Derivatives of the six trigonometric functions, with x in radians.', '[{"symbol":"x","meaning":"angle in radians"}]', 'published');
INSERT OR IGNORE INTO formulas (id, subject_id, slug, name, latex, description, variables, status) VALUES ('frm_82cb1b6c000c65', 'subj_math', 'exp-log-derivatives', 'Derivatives of exponential and logarithmic functions', '(e^x)'' = e^x,\quad (a^x)'' = a^x \ln a,\quad (\ln x)'' = \frac{1}{x},\quad (\log_a x)'' = \frac{1}{x \ln a}', 'Derivatives of exponential and logarithmic functions (a > 0, a ≠ 1; x > 0 for the logarithms).', '[{"symbol":"a","meaning":"base, a > 0 and a ≠ 1"}]', 'published');
INSERT OR IGNORE INTO formulas (id, subject_id, slug, name, latex, description, variables, status) VALUES ('frm_401f0135de8139', 'subj_math', 'inverse-derivatives', 'Derivatives of inverse functions', '(f^{-1})''(a) = \frac{1}{f''(f^{-1}(a))},\quad (\arcsin x)'' = \frac{1}{\sqrt{1 - x^2}},\quad (\arctan x)'' = \frac{1}{1 + x^2}', 'The slope of an inverse function is the reciprocal of the original slope at the matching point. Also (arccos x)′ = −1/√(1 − x²).', '[{"symbol":"f^{-1}","meaning":"inverse of a one-to-one differentiable f"}]', 'published');

-- Lesson: applied-rates-of-change
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_92137eeb36bd76', 'applied-rates-of-change', 'Rates of change in applied contexts other than motion', 'Use derivatives as rates in geometry, economics, biology and physical science, computing them from formulas and interpreting them with units.', 25, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_439ce10ed37f71', 'les_92137eeb36bd76', 1, 'Compute rates of change from formulas in non-motion contexts.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_8207543476962c', 'les_92137eeb36bd76', 2, 'Interpret marginal cost, growth rates and geometric rates.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_7a4114a79a7b58', 'les_92137eeb36bd76', 3, 'Use units to check whether a rate makes sense.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_439ce10ed37f71', 'les_92137eeb36bd76', 'learn', 1, 'definition', '{"term":"Any rate is a derivative","body":"Whenever one quantity depends on another, the derivative measures how fast the first changes per unit of the second: cost per item, people per year, square centimeters per centimeter of radius."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_8207543476962c', 'les_92137eeb36bd76', 'learn', 2, 'worked_example', '{"title":"Area of a circle $A = \\pi r^2$ at $r = 5$ cm","steps":[{"latex":"\\frac{dA}{dr} = 2\\pi r = 10\\pi \\approx 31.4 \\text{ cm}^2 \\text{ per cm}","explanation":"Equal to the circumference."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_7a4114a79a7b58', 'les_92137eeb36bd76', 'learn', 3, 'worked_example', '{"title":"Bacteria $N(t) = 500e^{0.2t}$, $t$ in hours","steps":[{"latex":"N''(t) = 100e^{0.2t}","explanation":""},{"latex":"N''(5) = 100e \\approx 272 \\text{ bacteria per hour}","explanation":""}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_7c895f8d58ed07', 'les_92137eeb36bd76', 'learn', 4, 'worked_example', '{"title":"Cost $C(q) = 2000 + 15q - 0.01q^2$ dollars","steps":[{"latex":"C''(q) = 15 - 0.02q","explanation":""},{"latex":"C''(200) = 11 \\text{ dollars per item}","explanation":"Marginal cost at 200 items."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_18bd42aa8013ac', 'les_92137eeb36bd76', 'learn', 5, 'callout', '{"tone":"application","title":"Where this shows up","body":"Pharmacologists track how fast a drug level falls; climate scientists report warming in °C per decade; both are derivatives."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_439ce10ed37f71', 'les_92137eeb36bd76', 1, 'practice', 'numeric', 1, 'For $C(q) = 2000 + 15q - 0.01q^2$, find $C''(500)$ in dollars per item.', '{"answer":5,"unit":"dollars per item"}', '[]', '$15 - 10 = 5$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_8207543476962c', 'les_92137eeb36bd76', 2, 'practice', 'numeric', 2, 'A cube''s volume is $V = s^3$. Find $\frac{dV}{ds}$ when $s = 4$ cm, in cm³ per cm.', '{"answer":48}', '[]', '$3s^2 = 48$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_7a4114a79a7b58', 'les_92137eeb36bd76', 3, 'practice', 'numeric', 2, '$N(t) = 500e^{0.2t}$. Find $N''(0)$ in bacteria per hour.', '{"answer":100}', '[]', '$100e^0 = 100$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_7c895f8d58ed07', 'les_92137eeb36bd76', 4, 'review', 'multiple_choice', 3, 'The volume of a gas at constant temperature is $V = \frac{k}{P}$. What is the sign of $\frac{dV}{dP}$, and what does it mean?', '{"choices":["Positive: more pressure, more volume","Negative: increasing pressure decreases volume","Zero: volume doesn''t depend on pressure","Undefined"],"answer":1}', '[]', '$\frac{dV}{dP} = -\frac{k}{P^2} < 0$ (Boyle''s law).');
INSERT OR IGNORE INTO concepts (id, subject_id, slug, name, description) VALUES ('cpt_36377b1d43a313', 'subj_math', 'derivatives', 'Derivatives', 'The instantaneous rate of change of a function; the slope of its tangent line.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_92137eeb36bd76', (SELECT id FROM concepts WHERE slug = 'derivatives'));

-- Lesson: average-instantaneous-rates
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_6a0529b0050b8a', 'average-instantaneous-rates', 'Defining average and instantaneous rates of change', 'Compute average rates of change over intervals, and define the instantaneous rate of change as the limit of average rates over shrinking intervals.', 25, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_96bc4563cd6c30', 'les_6a0529b0050b8a', 1, 'Compute an average rate of change with units.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_e9a241a694c5c0', 'les_6a0529b0050b8a', 2, 'Express an instantaneous rate of change as a limit of difference quotients.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_50a4c24a23e20d', 'les_6a0529b0050b8a', 3, 'Interpret both as slopes: secant and tangent.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_96bc4563cd6c30', 'les_6a0529b0050b8a', 'learn', 1, 'definition', '{"term":"Average rate of change","body":"On $[a, b]$: $\\frac{f(b) - f(a)}{b - a}$, the slope of the secant line through $(a, f(a))$ and $(b, f(b))$."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_e9a241a694c5c0', 'les_6a0529b0050b8a', 'learn', 2, 'definition', '{"term":"Instantaneous rate of change","body":"At $x = a$: $\\lim_{h \\to 0} \\frac{f(a + h) - f(a)}{h}$, the slope of the tangent line, when the limit exists."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_50a4c24a23e20d', 'les_6a0529b0050b8a', 'learn', 3, 'worked_example', '{"title":"A ball falls $s(t) = 16t^2$ feet in $t$ seconds.","steps":[{"latex":"\\text{average on } [1, 3]: \\tfrac{144 - 16}{2} = 64 \\text{ ft/s}","explanation":""},{"latex":"\\frac{16(2 + h)^2 - 64}{h} = 64 + 16h","explanation":"Average velocity on [2, 2 + h]."},{"latex":"\\lim_{h \\to 0} (64 + 16h) = 64 \\text{ ft/s}","explanation":"Instantaneous velocity at t = 2."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_d5ef44c57abdb1', 'les_6a0529b0050b8a', 'experiment', 4, 'activity', '{"activity":"tangent-line","title":"Shrink the interval","params":{"fn":"x^2"}}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_115bc4724f086b', 'les_6a0529b0050b8a', 'experiment', 5, 'callout', '{"tone":"tip","title":"Try this","body":"Set $a = 1$ and slide $h$ toward 0 from both sides. The orange secant slope closes in on the green tangent slope, 2."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_fde9d5c7a165c9', 'les_6a0529b0050b8a', 'learn', 6, 'callout', '{"tone":"application","title":"Where this shows up","body":"A car''s trip computer reports average speed; its speedometer reports instantaneous speed. Calculus is the bridge between the two."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_96bc4563cd6c30', 'les_6a0529b0050b8a', 1, 'practice', 'numeric', 1, 'Find the average rate of change of $f(x) = x^3$ on $[1, 3]$.', '{"answer":13}', '[]', '$\frac{27 - 1}{2} = 13$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_e9a241a694c5c0', 'les_6a0529b0050b8a', 2, 'practice', 'numeric', 2, 'Water volume is $V(t) = 200 - 4t^2$ liters. Find the average rate of change on $[0, 5]$, in liters per minute.', '{"answer":-20,"unit":"L/min"}', '[]', '$\frac{100 - 200}{5} = -20$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_50a4c24a23e20d', 'les_6a0529b0050b8a', 3, 'practice', 'numeric', 2, 'Use the limit to find the instantaneous rate of change of $f(x) = x^3$ at $x = 2$.', '{"answer":12}', '["$(2 + h)^3 = 8 + 12h + 6h^2 + h^3$."]', '$\frac{12h + 6h^2 + h^3}{h} \to 12$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_d5ef44c57abdb1', 'les_6a0529b0050b8a', 4, 'review', 'numeric', 3, 'For $s(t) = 16t^2$, find the average velocity on $[2, 2.1]$, in ft/s.', '{"answer":65.6,"tolerance":0.01,"unit":"ft/s"}', '[]', '$64 + 16(0.1) = 65.6$, close to the instantaneous 64.');
