-- Lesson: basic-derivative-rules
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_4711fea3f062f3', 'basic-derivative-rules', 'Derivative rules: constant, sum, difference and constant multiple', 'Differentiate polynomials and sums of powers term by term using the constant, constant multiple, sum and difference rules, and find horizontal tangents.', 25, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_948653c355fd42', 'les_4711fea3f062f3', 1, 'Apply the constant, constant multiple, sum and difference rules.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_ad670d6438d9d7', 'les_4711fea3f062f3', 2, 'Differentiate polynomials and sums of power functions.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_bf770fa8dca502', 'les_4711fea3f062f3', 3, 'Find where a graph has horizontal tangent lines.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_948653c355fd42', 'les_4711fea3f062f3', 'learn', 1, 'definition', '{"term":"Rules","body":"$\\frac{d}{dx}c = 0$; $\\frac{d}{dx}[c f(x)] = c f''(x)$; $\\frac{d}{dx}[f(x) \\pm g(x)] = f''(x) \\pm g''(x)$."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_ad670d6438d9d7', 'les_4711fea3f062f3', 'learn', 2, 'worked_example', '{"title":"$f(x) = 3x^4 - 5x^2 + 7x - 2$","steps":[{"latex":"f''(x) = 12x^3 - 10x + 7","explanation":"Term by term."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_bf770fa8dca502', 'les_4711fea3f062f3', 'learn', 3, 'worked_example', '{"title":"Where does $y = x^3 - 3x$ have horizontal tangents?","steps":[{"latex":"y'' = 3x^2 - 3 = 0","explanation":""},{"latex":"x = \\pm 1","explanation":"Points (1, −2) and (−1, 2)."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_a685a48e5520fd', 'les_4711fea3f062f3', 'experiment', 4, 'activity', '{"activity":"derivative-graph","title":"Find the flat spots","params":{"fn":"cubic","a":-1}}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_e43e7669f66ef9', 'les_4711fea3f062f3', 'experiment', 5, 'callout', '{"tone":"tip","title":"Try this","body":"Move $a$ to $-1$ and to $1$: the tangent is horizontal and $f''(a) = 0$. Then switch to $\\frac{1}{4}x^4 - x^2$ and find its three flat spots."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_8f51b982f07da4', 'les_4711fea3f062f3', 'learn', 6, 'callout', '{"tone":"application","title":"Where this shows up","body":"If revenue is $R(q) = 50q - 0.02q^2$, then $R''(q) = 50 - 0.04q$ tells how much each additional sale adds, and $R'' = 0$ at $q = 1250$ marks maximum revenue."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_948653c355fd42', 'les_4711fea3f062f3', 1, 'practice', 'numeric', 1, 'If $f(x) = 4x^3 - \frac{2}{x}$, find $f''(1)$.', '{"answer":14}', '["$-\\frac{2}{x} = -2x^{-1}$."]', '$12x^2 + 2x^{-2} = 14$ at 1.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_ad670d6438d9d7', 'les_4711fea3f062f3', 2, 'practice', 'numeric', 2, 'At what $x$ does $y = x^2 - 8x + 3$ have a horizontal tangent?', '{"answer":4}', '[]', '$2x - 8 = 0$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_bf770fa8dca502', 'les_4711fea3f062f3', 3, 'practice', 'multiple_choice', 2, '$\frac{d}{dx}(\pi^2 + 5x)$ is…', '{"choices":["$2\\pi + 5$","5","$\\pi^2 + 5$","0"],"answer":1}', '[]', '$\pi^2$ is a constant.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_a685a48e5520fd', 'les_4711fea3f062f3', 4, 'review', 'numeric', 3, 'Revenue is $R(q) = 50q - 0.02q^2$. Find $R''(1000)$ in dollars per item.', '{"answer":10,"unit":"dollars per item"}', '[]', '$50 - 0.04(1000) = 10$.');
