-- Lesson: chain-rule
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_45b7fb88cca2f3', 'chain-rule', 'The Chain Rule', 'Differentiate compositions with the Chain Rule, identify inner and outer functions, and use it with tables, graphs and other rules.', 30, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_602bf533cbf4f9', 'les_45b7fb88cca2f3', 1, 'Identify the inner and outer functions of a composition.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_ad2c9a75785a40', 'les_45b7fb88cca2f3', 2, 'Apply d/dx f(g(x)) = f′(g(x))·g′(x), including repeated use.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_f660b118e53ca3', 'les_45b7fb88cca2f3', 3, 'Use the Chain Rule with tables of values.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_602bf533cbf4f9', 'les_45b7fb88cca2f3', 'learn', 1, 'definition', '{"term":"Chain Rule","body":"If $y = f(u)$ and $u = g(x)$, then $\\frac{dy}{dx} = \\frac{dy}{du}\\cdot\\frac{du}{dx}$, that is, $\\frac{d}{dx}f(g(x)) = f''(g(x))\\,g''(x)$: the derivative of the outside, evaluated at the inside, times the derivative of the inside."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_ad2c9a75785a40', 'les_45b7fb88cca2f3', 'learn', 2, 'worked_example', '{"title":"Common patterns","steps":[{"latex":"\\frac{d}{dx}(3x + 1)^5 = 5(3x + 1)^4 \\cdot 3","explanation":""},{"latex":"\\frac{d}{dx}\\sin(x^2) = \\cos(x^2) \\cdot 2x","explanation":""},{"latex":"\\frac{d}{dx}e^{-2x} = -2e^{-2x}","explanation":""},{"latex":"\\frac{d}{dx}\\ln(x^2 + 1) = \\frac{2x}{x^2 + 1}","explanation":""}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_f660b118e53ca3', 'les_45b7fb88cca2f3', 'learn', 3, 'worked_example', '{"title":"$h(x) = f(g(x))$ with $g(1) = 3$, $g''(1) = 2$, $f''(3) = -4$","steps":[{"latex":"h''(1) = f''(g(1)) \\cdot g''(1) = f''(3) \\cdot 2","explanation":""},{"latex":"= -8","explanation":""}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_9b66ead795de02', 'les_45b7fb88cca2f3', 'learn', 4, 'worked_example', '{"title":"$\\frac{d}{dx}\\cos^3(2x) = \\frac{d}{dx}[\\cos(2x)]^3$","steps":[{"latex":"3\\cos^2(2x) \\cdot (-\\sin 2x) \\cdot 2","explanation":"Three layers: cube, cosine, 2x."},{"latex":"= -6\\cos^2(2x)\\sin(2x)","explanation":""}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_86aecb3549985f', 'les_45b7fb88cca2f3', 'learn', 5, 'callout', '{"tone":"application","title":"Where this shows up","body":"If air temperature changes with altitude and a balloon''s altitude changes with time, the rate the balloon''s thermometer changes is (°C per meter) × (meters per second)."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_602bf533cbf4f9', 'les_45b7fb88cca2f3', 1, 'practice', 'numeric', 1, 'Find $\frac{d}{dx}\sqrt{x^2 + 9}$ at $x = 4$.', '{"answer":0.8,"tolerance":0.001}', '[]', '$\frac{x}{\sqrt{x^2 + 9}} = \frac{4}{5}$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_ad2c9a75785a40', 'les_45b7fb88cca2f3', 2, 'practice', 'numeric', 2, '$g(2) = 5$, $g''(2) = -3$, $f''(5) = 2$. Find $(f \circ g)''(2)$.', '{"answer":-6}', '[]', '$f''(5)g''(2) = -6$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_f660b118e53ca3', 'les_45b7fb88cca2f3', 3, 'practice', 'multiple_choice', 2, '$\frac{d}{dx}e^{\sin x}$ is…', '{"choices":["$e^{\\sin x}$","$e^{\\cos x}$","$\\cos x\\, e^{\\sin x}$","$\\sin x\\, e^{\\sin x - 1}$"],"answer":2}', '[]', 'Outside $e^u$, inside $\sin x$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_9b66ead795de02', 'les_45b7fb88cca2f3', 4, 'review', 'numeric', 3, 'Find $\frac{d}{dx}\ln(\cos x)$ at $x = \frac{\pi}{4}$.', '{"answer":-1}', '[]', '$\frac{-\sin x}{\cos x} = -\tan x = -1$.');
INSERT OR IGNORE INTO concepts (id, subject_id, slug, name, description) VALUES ('cpt_36377b1d43a313', 'subj_math', 'derivatives', 'Derivatives', 'The instantaneous rate of change of a function; the slope of its tangent line.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_45b7fb88cca2f3', (SELECT id FROM concepts WHERE slug = 'derivatives'));
INSERT OR IGNORE INTO lesson_formulas (lesson_id, formula_id, position) VALUES ('les_45b7fb88cca2f3', (SELECT id FROM formulas WHERE slug = 'chain-rule'), 1);

-- Lesson: continuity-intervals
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_18f720c58a7630', 'continuity-intervals', 'Defining continuity at a point and over an interval', 'Use the three-part definition of continuity, extend it to intervals with one-sided continuity at endpoints, and choose constants that make piecewise functions continuous.', 25, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_869a13d8bcff6e', 'les_18f720c58a7630', 1, 'Check continuity at a point: f(c) defined, limit exists, and they are equal.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_c63f7c97449dd7', 'les_18f720c58a7630', 2, 'Decide whether a function is continuous on an open or closed interval.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_7eb438d8cbf440', 'les_18f720c58a7630', 3, 'Find constants that make a piecewise function continuous.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_869a13d8bcff6e', 'les_18f720c58a7630', 'learn', 1, 'definition', '{"term":"Continuity at a point","body":"$f$ is continuous at $c$ if (1) $f(c)$ is defined, (2) $\\lim_{x \\to c} f(x)$ exists, and (3) $\\lim_{x \\to c} f(x) = f(c)$."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_c63f7c97449dd7', 'les_18f720c58a7630', 'learn', 2, 'figure', '{"src":"/figures/discontinuity-types.svg","alt":"Three graphs. Removable: a line with a hole where the function''s value is plotted elsewhere. Jump: the graph jumps from one height to another. Infinite: the graph shoots up and down beside a vertical asymptote.","caption":"Each graph fails a different condition of the definition."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_7eb438d8cbf440', 'les_18f720c58a7630', 'learn', 3, 'definition', '{"term":"On an interval","body":"$f$ is continuous on $(a, b)$ if it is continuous at every point inside. On $[a, b]$ it must also be continuous from the right at $a$ ($\\lim_{x \\to a^+} f(x) = f(a)$) and from the left at $b$. Polynomials, rational, exponential, logarithmic and trig functions are continuous on their domains."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_b20cb4d74ff027', 'les_18f720c58a7630', 'learn', 4, 'worked_example', '{"title":"Find $k$ so $f(x) = kx + 1$ for $x < 2$ and $f(x) = x^2$ for $x \\ge 2$ is continuous.","steps":[{"latex":"\\lim_{x \\to 2^-} f(x) = 2k + 1","explanation":""},{"latex":"\\lim_{x \\to 2^+} f(x) = 4 = f(2)","explanation":""},{"latex":"2k + 1 = 4 \\Rightarrow k = 1.5","explanation":"The pieces must meet."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_f13b34e57b5a96', 'les_18f720c58a7630', 'learn', 5, 'callout', '{"tone":"application","title":"Where this shows up","body":"Tax brackets and shipping rates are piecewise; engineers choose constants so connected pieces of a road or track join without a jump."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_869a13d8bcff6e', 'les_18f720c58a7630', 1, 'practice', 'numeric', 2, '$f(x) = ax - 3$ for $x \le 1$ and $f(x) = 2x^2 + 1$ for $x > 1$. Find $a$ so $f$ is continuous.', '{"answer":6}', '[]', '$a - 3 = 3$, so $a = 6$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_c63f7c97449dd7', 'les_18f720c58a7630', 2, 'practice', 'multiple_choice', 1, 'On which interval is $f(x) = \frac{1}{x - 4}$ continuous?', '{"choices":["$(-\\infty, \\infty)$","$[0, 5]$","$(4, \\infty)$","$[4, 8]$"],"answer":2}', '[]', 'It''s continuous everywhere except $x = 4$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_7eb438d8cbf440', 'les_18f720c58a7630', 3, 'practice', 'multiple_choice', 2, '$\lim_{x \to 3} f(x) = 7$ and $f(3) = 5$. Which condition fails?', '{"choices":["f(3) is defined","The limit exists","The limit equals f(3)","None"],"answer":2}', '[]', 'The limit and the value differ.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_b20cb4d74ff027', 'les_18f720c58a7630', 4, 'review', 'multiple_choice', 3, 'Is $f(x) = \sqrt{x}$ continuous on $[0, 4]$?', '{"choices":["Yes: continuous inside and from the right at 0, from the left at 4","No, because f(0) = 0","No, because the limit at 0 doesn''t exist","Only on (0, 4)"],"answer":0}', '[]', 'At the endpoint 0 only the right-hand limit is needed, and it equals $f(0) = 0$.');
INSERT OR IGNORE INTO concepts (id, subject_id, slug, name, description) VALUES ('cpt_1d074decbcdb94', 'subj_math', 'continuity', 'Continuity', 'A function is continuous at c when its limit at c exists and equals f(c).');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_18f720c58a7630', (SELECT id FROM concepts WHERE slug = 'continuity'));

-- Lesson: derivative-definition
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_b85060863d3c28', 'derivative-definition', 'Defining the derivative of a function and using derivative notation', 'Define the derivative as a limit, compute it from the definition, read the notations f′(x), dy/dx and d/dx, and write tangent line equations.', 30, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_3933c14ec90fb5', 'les_b85060863d3c28', 1, 'Compute f′(x) from the limit definition for simple functions.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_2343e4a2322aa3', 'les_b85060863d3c28', 2, 'Use the notations f′(x), y′, dy/dx and d/dx[f(x)].');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_286fc37498c853', 'les_b85060863d3c28', 3, 'Recognize a limit as the derivative of some function at a point, and write a tangent line.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_3933c14ec90fb5', 'les_b85060863d3c28', 'learn', 1, 'definition', '{"term":"The derivative","body":"$f''(x) = \\lim_{h \\to 0} \\frac{f(x + h) - f(x)}{h}$, wherever the limit exists. At a point, the equivalent form $f''(a) = \\lim_{x \\to a} \\frac{f(x) - f(a)}{x - a}$ is also common."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_2343e4a2322aa3', 'les_b85060863d3c28', 'learn', 2, 'worked_example', '{"title":"$f(x) = x^2$","steps":[{"latex":"\\frac{(x + h)^2 - x^2}{h} = \\frac{2xh + h^2}{h}","explanation":""},{"latex":"= 2x + h \\to 2x","explanation":"So $f''(x) = 2x$."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_286fc37498c853', 'les_b85060863d3c28', 'learn', 3, 'worked_example', '{"title":"$f(x) = \\dfrac{1}{x}$","steps":[{"latex":"\\frac{\\frac{1}{x + h} - \\frac{1}{x}}{h} = \\frac{-h}{h\\,x(x + h)}","explanation":"Combine fractions."},{"latex":"= \\frac{-1}{x(x + h)} \\to -\\frac{1}{x^2}","explanation":""}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_70800dd9992b53', 'les_b85060863d3c28', 'learn', 4, 'worked_example', '{"title":"Tangent line to $y = x^2$ at $x = 3$","steps":[{"latex":"f(3) = 9,\\ f''(3) = 6","explanation":""},{"latex":"y - 9 = 6(x - 3)","explanation":"Point-slope form."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_cdfda5569b097d', 'les_b85060863d3c28', 'experiment', 5, 'activity', '{"activity":"derivative-graph","title":"The slope of f becomes the height of f′","params":{"fn":"cubic","a":1.5}}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_4168904ad69c07', 'les_b85060863d3c28', 'experiment', 6, 'callout', '{"tone":"tip","title":"Try this","body":"Slide $a$ across the graph. Where $f$ has a peak or valley, the tangent is flat and the lower graph crosses zero."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_3e294e09c85b7c', 'les_b85060863d3c28', 'learn', 7, 'callout', '{"tone":"application","title":"Where this shows up","body":"If $C(q)$ is the cost of producing $q$ items, $C''(q)$ is the marginal cost: about how much the next item costs."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_3933c14ec90fb5', 'les_b85060863d3c28', 1, 'practice', 'numeric', 2, 'Evaluate $\lim_{h \to 0} \dfrac{(2 + h)^3 - 8}{h}$.', '{"answer":12}', '["It''s f′(2) for f(x) = x³."]', '$f''(x) = 3x^2$, so $f''(2) = 12$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_2343e4a2322aa3', 'les_b85060863d3c28', 2, 'practice', 'multiple_choice', 2, 'Which equals $f''(5)$?', '{"choices":["$\\lim_{x \\to 5} \\frac{f(x) - f(5)}{x - 5}$","$\\frac{f(5 + h) - f(5)}{h}$","$\\lim_{h \\to 0} f(5 + h)$","$\\frac{f(5)}{5}$"],"answer":0}', '[]', 'The alternate form of the definition.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_286fc37498c853', 'les_b85060863d3c28', 3, 'practice', 'numeric', 2, 'Using $f(x) = x^2$, find the $y$-intercept of the tangent line at $x = 3$.', '{"answer":-9}', '[]', '$y = 9 + 6(x - 3) = 6x - 9$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_70800dd9992b53', 'les_b85060863d3c28', 4, 'review', 'numeric', 3, 'From the definition, $\frac{d}{dx}\sqrt{x} = \frac{1}{2\sqrt{x}}$. Find the slope of $y = \sqrt{x}$ at $x = 9$, to four decimal places.', '{"answer":0.1667,"tolerance":0.0001}', '[]', '$\frac{1}{6} \approx 0.1667$.');
INSERT OR IGNORE INTO concepts (id, subject_id, slug, name, description) VALUES ('cpt_36377b1d43a313', 'subj_math', 'derivatives', 'Derivatives', 'The instantaneous rate of change of a function; the slope of its tangent line.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_b85060863d3c28', (SELECT id FROM concepts WHERE slug = 'derivatives'));
INSERT OR IGNORE INTO lesson_formulas (lesson_id, formula_id, position) VALUES ('les_b85060863d3c28', (SELECT id FROM formulas WHERE slug = 'derivative-definition'), 1);

-- Lesson: derivative-in-context
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_3e29398309faea', 'derivative-in-context', 'Interpreting the meaning of the derivative in context', 'Interpret f′(a) in a real situation with the correct units, sign and time or input reference, and distinguish it from f(a) and from average rates.', 20, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_0d8ae4b2de79ba', 'les_3e29398309faea', 1, 'Write a complete interpretation of f′(a): what changes, how fast, in what units, at what input.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_984df11f52a125', 'les_3e29398309faea', 2, 'Explain what a positive, negative or zero derivative means in context.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_5dd8f2682a4611', 'les_3e29398309faea', 3, 'Avoid interpreting a rate as an amount.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_0d8ae4b2de79ba', 'les_3e29398309faea', 'learn', 1, 'definition', '{"term":"A complete interpretation","body":"\"At [input value with units], [output quantity] is [increasing/decreasing] at a rate of [|f′(a)|] [output units] per [input unit].\" The units of $f''$ are output units divided by input units."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_984df11f52a125', 'les_3e29398309faea', 'learn', 2, 'worked_example', '{"title":"$V(t)$ is the water in a tank, in liters, $t$ minutes after noon. $V''(3) = -2$.","steps":[{"latex":"\\text{units: liters per minute}","explanation":""},{"latex":"\\text{at 12:03 p.m., the water is decreasing at 2 L/min}","explanation":"Not ''the tank has 2 liters'' and not ''it lost 2 liters over 3 minutes.''"}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_5dd8f2682a4611', 'les_3e29398309faea', 'learn', 3, 'worked_example', '{"title":"$C(q)$ is the cost in dollars of making $q$ bicycles. $C''(100) = 85$.","steps":[{"latex":"\\text{when 100 bikes are being made, cost rises about 85 dollars per additional bike}","explanation":"So the 101st bike costs about 85 dollars."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_62814ba173b736', 'les_3e29398309faea', 'learn', 4, 'callout', '{"tone":"warning","title":"Rate vs amount","body":"$V(3)$ is an amount (liters). $V''(3)$ is a rate (liters per minute). Mixing them up is the most common error."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_d900826114b8a6', 'les_3e29398309faea', 'learn', 5, 'callout', '{"tone":"application","title":"Where this shows up","body":"Economists call derivatives \"marginal\" quantities; physicians read the rate of change of a drug level, not just the level, to adjust doses."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_0d8ae4b2de79ba', 'les_3e29398309faea', 1, 'practice', 'multiple_choice', 1, '$h(t)$ is a plant''s height in cm, $t$ in days. The units of $h''(t)$ are…', '{"choices":["cm","days","cm per day","days per cm"],"answer":2}', '[]', 'Output units per input unit.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_984df11f52a125', 'les_3e29398309faea', 2, 'practice', 'multiple_choice', 2, '$P(t)$ is a town''s population, $t$ years after 2020. $P''(5) = -120$ means…', '{"choices":["The population in 2025 was −120","In 2025 the population was decreasing at about 120 people per year","The population fell 120 people from 2020 to 2025","The population will be 120 in 5 years"],"answer":1}', '[]', 'A rate at the moment $t = 5$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_5dd8f2682a4611', 'les_3e29398309faea', 3, 'practice', 'multiple_choice', 2, '$T(x)$ is the temperature in °C at depth $x$ meters in a lake, and $T''(10) = -0.4$. Which is correct?', '{"choices":["At 10 m deep, the water is 0.4 °C","At 10 m deep, temperature drops about 0.4 °C per additional meter of depth","The lake cools 0.4 °C per hour","At 10 m the temperature is decreasing over time"],"answer":1}', '[]', 'The input is depth, not time.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_62814ba173b736', 'les_3e29398309faea', 4, 'review', 'multiple_choice', 3, '$C''(100) = 85$ for bicycle cost. Which is the best estimate of the cost of making 101 bikes, if $C(100) = 20{,}000$?', '{"choices":["85 dollars","20,000 dollars","20,085 dollars","28,500 dollars"],"answer":2}', '[]', '$C(101) \approx C(100) + C''(100)(1)$.');
INSERT OR IGNORE INTO concepts (id, subject_id, slug, name, description) VALUES ('cpt_36377b1d43a313', 'subj_math', 'derivatives', 'Derivatives', 'The instantaneous rate of change of a function; the slope of its tangent line.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_3e29398309faea', (SELECT id FROM concepts WHERE slug = 'derivatives'));

-- Lesson: derivatives-sin-cos-exp-ln
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_0285903d619f5f', 'derivatives-sin-cos-exp-ln', 'Derivatives of cos x, sin x, eˣ and ln x', 'Learn and use the derivatives of sin x, cos x, eˣ and ln x, see where they come from, and combine them with the basic rules.', 25, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_f9bbac281fbcfa', 'les_0285903d619f5f', 1, 'Use (sin x)′ = cos x, (cos x)′ = −sin x, (eˣ)′ = eˣ and (ln x)′ = 1/x.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_dc0869d7c72e97', 'les_0285903d619f5f', 2, 'Explain how the special trig limits give the derivative of sin x.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_08057be8f29727', 'les_0285903d619f5f', 3, 'Write tangent lines for these functions.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_f9bbac281fbcfa', 'les_0285903d619f5f', 'learn', 1, 'definition', '{"term":"Four derivatives","body":"$\\frac{d}{dx}\\sin x = \\cos x$, $\\frac{d}{dx}\\cos x = -\\sin x$, $\\frac{d}{dx}e^x = e^x$, $\\frac{d}{dx}\\ln x = \\frac{1}{x}$ (with $x$ in radians for the trig functions)."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_dc0869d7c72e97', 'les_0285903d619f5f', 'learn', 2, 'worked_example', '{"title":"Where $(\\sin x)'' = \\cos x$ comes from","steps":[{"latex":"\\frac{\\sin(x + h) - \\sin x}{h}","explanation":""},{"latex":"= \\sin x\\,\\frac{\\cos h - 1}{h} + \\cos x\\,\\frac{\\sin h}{h}","explanation":"Angle-sum identity."},{"latex":"\\to \\sin x \\cdot 0 + \\cos x \\cdot 1","explanation":"Special limits."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_08057be8f29727', 'les_0285903d619f5f', 'learn', 3, 'worked_example', '{"title":"$f(x) = 3\\sin x - 2e^x + \\ln x$","steps":[{"latex":"f''(x) = 3\\cos x - 2e^x + \\tfrac{1}{x}","explanation":""}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_4c80cad28d50f9', 'les_0285903d619f5f', 'learn', 4, 'worked_example', '{"title":"Tangent to $y = \\ln x$ at $x = 1$","steps":[{"latex":"y(1) = 0,\\ y''(1) = 1","explanation":""},{"latex":"y = x - 1","explanation":""}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_8c7b0f686d2d6a', 'les_0285903d619f5f', 'experiment', 5, 'activity', '{"activity":"derivative-graph","title":"Sine and its derivative","params":{"fn":"sin","a":0}}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_44bc85ba8e6bf8', 'les_0285903d619f5f', 'experiment', 6, 'callout', '{"tone":"tip","title":"Try this","body":"With $\\sin x$, the lower graph is exactly $\\cos x$. Switch to $e^x$: the two graphs are identical, since $e^x$ is its own derivative."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_68c31e650637a4', 'les_0285903d619f5f', 'learn', 7, 'callout', '{"tone":"application","title":"Where this shows up","body":"A mass on a spring at position $\\sin t$ has velocity $\\cos t$: fastest when passing through the middle, momentarily still at the ends."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_f9bbac281fbcfa', 'les_0285903d619f5f', 1, 'practice', 'numeric', 1, 'If $f(x) = 5\cos x$, find $f''\left(\frac{\pi}{2}\right)$.', '{"answer":-5}', '[]', '$-5\sin\frac{\pi}{2} = -5$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_dc0869d7c72e97', 'les_0285903d619f5f', 2, 'practice', 'numeric', 2, 'If $f(x) = e^x - \ln x$, find $f''(1)$ to three decimal places.', '{"answer":1.718,"tolerance":0.001}', '[]', '$e - 1 \approx 1.718$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_08057be8f29727', 'les_0285903d619f5f', 3, 'practice', 'multiple_choice', 2, 'What is the slope of $y = e^x$ at $x = 0$?', '{"choices":["0","1","e","undefined"],"answer":1}', '[]', '$e^0 = 1$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_4c80cad28d50f9', 'les_0285903d619f5f', 4, 'review', 'multiple_choice', 3, 'Why must $x$ be in radians for $(\sin x)'' = \cos x$?', '{"choices":["Degrees are not real numbers","The limit sin h / h = 1 holds only for radians","Cosine is defined only in radians","It doesn''t matter"],"answer":1}', '[]', 'In degrees, $\frac{\sin h°}{h} \to \frac{\pi}{180}$.');
INSERT OR IGNORE INTO concepts (id, subject_id, slug, name, description) VALUES ('cpt_36377b1d43a313', 'subj_math', 'derivatives', 'Derivatives', 'The instantaneous rate of change of a function; the slope of its tangent line.');
