-- Lesson: differentiability-continuity
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_c79961b8d08677', 'differentiability-continuity', 'Connecting differentiability and continuity', 'Show that differentiability implies continuity but not the reverse, recognize corners, cusps, vertical tangents and discontinuities, and make piecewise functions differentiable.', 25, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_3753150f1c9360', 'les_c79961b8d08677', 1, 'Explain why a differentiable function must be continuous.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_ff8d356b0dc64d', 'les_c79961b8d08677', 2, 'Identify where a function fails to be differentiable.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_1e30d5beab250c', 'les_c79961b8d08677', 3, 'Choose constants to make a piecewise function differentiable.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_3753150f1c9360', 'les_c79961b8d08677', 'learn', 1, 'definition', '{"term":"The connection","body":"If $f$ is differentiable at $a$, then $f$ is continuous at $a$. The converse is false: $|x|$ is continuous at 0 but not differentiable there."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_ff8d356b0dc64d', 'les_c79961b8d08677', 'learn', 2, 'figure', '{"src":"/figures/not-differentiable.svg","alt":"Four graphs that are not differentiable at x = 0: a corner on the absolute value graph, a cusp on x to the two-thirds power, a vertical tangent on the cube root graph, and a jump discontinuity.","caption":"Four ways to fail: corner, cusp, vertical tangent, discontinuity."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_1e30d5beab250c', 'les_c79961b8d08677', 'learn', 3, 'worked_example', '{"title":"Make $f(x) = x^2$ for $x \\le 1$ and $f(x) = ax + b$ for $x > 1$ differentiable.","steps":[{"latex":"\\text{continuity: } 1 = a + b","explanation":"The pieces must meet."},{"latex":"\\text{slopes: } 2x \\big|_{x = 1} = a \\Rightarrow a = 2","explanation":"The slopes must match."},{"latex":"b = -1","explanation":"So $f(x) = 2x - 1$ for $x > 1$: the tangent line at 1."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_bfbf099aa77ed2', 'les_c79961b8d08677', 'learn', 4, 'callout', '{"tone":"warning","title":"Matching slopes isn''t enough","body":"Both conditions are needed. Pieces with equal slopes that don''t meet give a jump, which isn''t even continuous."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_bf09def835f34c', 'les_c79961b8d08677', 'learn', 5, 'callout', '{"tone":"application","title":"Where this shows up","body":"Roller-coaster and road designers join curves so both position and slope match; a corner would mean a sudden change in direction."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_3753150f1c9360', 'les_c79961b8d08677', 1, 'practice', 'multiple_choice', 1, '$f$ is differentiable at 3. Which must be true?', '{"choices":["f is continuous at 3","f′(3) = 0","f(3) = 0","f is increasing"],"answer":0}', '[]', 'Differentiable implies continuous.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_ff8d356b0dc64d', 'les_c79961b8d08677', 2, 'practice', 'multiple_choice', 2, 'At $x = 0$, $f(x) = x^{1/3}$ has…', '{"choices":["a corner","a cusp","a vertical tangent","a jump"],"answer":2}', '[]', '$f''(x) = \frac{1}{3}x^{-2/3}$ grows without bound near 0.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_1e30d5beab250c', 'les_c79961b8d08677', 3, 'practice', 'numeric', 2, '$f(x) = x^3$ for $x \le 2$ and $f(x) = mx + c$ for $x > 2$ is differentiable. Find $m$.', '{"answer":12}', '[]', '$m = 3(2)^2 = 12$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_bfbf099aa77ed2', 'les_c79961b8d08677', 4, 'review', 'numeric', 3, 'For that function, find $c$.', '{"answer":-16}', '[]', '$8 = 24 + c$, so $c = -16$.');
INSERT OR IGNORE INTO concepts (id, subject_id, slug, name, description) VALUES ('cpt_36377b1d43a313', 'subj_math', 'derivatives', 'Derivatives', 'The instantaneous rate of change of a function; the slope of its tangent line.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_c79961b8d08677', (SELECT id FROM concepts WHERE slug = 'derivatives'));
INSERT OR IGNORE INTO concepts (id, subject_id, slug, name, description) VALUES ('cpt_1d074decbcdb94', 'subj_math', 'continuity', 'Continuity', 'A function is continuous at c when its limit at c exists and equals f(c).');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_c79961b8d08677', (SELECT id FROM concepts WHERE slug = 'continuity'));

-- Lesson: estimating-derivatives
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_ec2507810834b9', 'estimating-derivatives', 'Estimating derivatives at a point', 'Estimate derivatives from tables and graphs using difference quotients, choose the best interval around the point, and interpret the estimate with units.', 25, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_341d1c383aff18', 'les_ec2507810834b9', 1, 'Estimate f′(a) from a table using the closest values on either side of a.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_3e25d33da75941', 'les_ec2507810834b9', 2, 'Estimate a derivative from a graph by drawing a tangent line.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_5f2915e112bdb0', 'les_ec2507810834b9', 3, 'State the estimate with correct units and interpret it in context.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_341d1c383aff18', 'les_ec2507810834b9', 'learn', 1, 'definition', '{"term":"Estimating from a table","body":"If $a$ is between two table values $x_1 < a < x_2$, use $f''(a) \\approx \\frac{f(x_2) - f(x_1)}{x_2 - x_1}$. Use the closest values available; a symmetric interval around $a$ usually gives the best estimate."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_3e25d33da75941', 'les_ec2507810834b9', 'learn', 2, 'worked_example', '{"title":"Coffee temperature $T(t)$ in °C, $t$ in minutes: $T(0) = 90$, $T(5) = 60$, $T(10) = 52$, $T(15) = 46$. Estimate $T''(7)$.","steps":[{"latex":"T''(7) \\approx \\frac{T(10) - T(5)}{10 - 5} = \\frac{52 - 60}{5}","explanation":"Closest values around 7."},{"latex":"= -1.6 \\ \\text{°C per minute}","explanation":"At t = 7 the coffee is cooling about 1.6 °C per minute."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_5f2915e112bdb0', 'les_ec2507810834b9', 'learn', 3, 'definition', '{"term":"Estimating from a graph","body":"Sketch the tangent line at the point, pick two points on it far apart, and compute its slope."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_37be6163fe1527', 'les_ec2507810834b9', 'learn', 4, 'callout', '{"tone":"tip","title":"Units","body":"The units of $f''(x)$ are (units of $f$) per (unit of $x$). Always include them."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_ba47389222ffa0', 'les_ec2507810834b9', 'learn', 5, 'callout', '{"tone":"application","title":"Where this shows up","body":"Weather services estimate how fast pressure is falling from hourly readings: a derivative estimated from a table, used to forecast storms."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_341d1c383aff18', 'les_ec2507810834b9', 1, 'practice', 'numeric', 1, 'Using the coffee table, estimate $T''(12)$ in °C per minute.', '{"answer":-1.2,"tolerance":0.001,"unit":"°C/min"}', '[]', '$\frac{46 - 52}{5} = -1.2$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_3e25d33da75941', 'les_ec2507810834b9', 2, 'practice', 'numeric', 2, '$x$: 1, 2, 4, 5 and $f(x)$: 3, 7, 13, 14. Estimate $f''(3)$.', '{"answer":3}', '[]', '$\frac{13 - 7}{4 - 2} = 3$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_5f2915e112bdb0', 'les_ec2507810834b9', 3, 'practice', 'multiple_choice', 2, '$P(t)$ is a population in thousands, $t$ in years. $P''(4) \approx 2.5$ means…', '{"choices":["The population is 2,500","At t = 4 the population is growing about 2,500 people per year","The population grows 2.5% per year","In 4 years it will be 2,500"],"answer":1}', '[]', 'Units: thousands of people per year.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_37be6163fe1527', 'les_ec2507810834b9', 4, 'review', 'multiple_choice', 3, 'For estimating $f''(2)$, which table interval is usually best?', '{"choices":["[0, 4]","[1, 3]","[2, 6]","[1, 10]"],"answer":1}', '[]', 'Short and centered on 2.');
INSERT OR IGNORE INTO concepts (id, subject_id, slug, name, description) VALUES ('cpt_36377b1d43a313', 'subj_math', 'derivatives', 'Derivatives', 'The instantaneous rate of change of a function; the slope of its tangent line.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_ec2507810834b9', (SELECT id FROM concepts WHERE slug = 'derivatives'));

-- Lesson: higher-order-derivatives
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_8a4cce987204b1', 'higher-order-derivatives', 'Calculating higher-order derivatives', 'Compute second and higher derivatives, use their notation, interpret acceleration and concavity, and find patterns in repeated derivatives.', 25, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_eb9e338bed4d73', 'les_8a4cce987204b1', 1, 'Compute f″, f‴ and f⁽ⁿ⁾ and use the notations d²y/dx².');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_2927a394f3ee42', 'les_8a4cce987204b1', 2, 'Interpret the second derivative as acceleration and as a rate of change of slope.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_8c4effad9e1cb0', 'les_8a4cce987204b1', 3, 'Spot repeating patterns, such as in derivatives of sin x.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_eb9e338bed4d73', 'les_8a4cce987204b1', 'learn', 1, 'definition', '{"term":"Notation","body":"$f''''(x) = \\frac{d^2y}{dx^2} = \\frac{d}{dx}\\left(\\frac{dy}{dx}\\right)$; then $f''''''(x)$ and $f^{(n)}(x)$. If $s(t)$ is position, $s''(t) = v(t)$ is velocity and $s''''(t) = a(t)$ is acceleration."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_2927a394f3ee42', 'les_8a4cce987204b1', 'learn', 2, 'worked_example', '{"title":"$f(x) = x^4$","steps":[{"latex":"f'' = 4x^3,\\ f'''' = 12x^2","explanation":""},{"latex":"f'''''' = 24x,\\ f^{(4)} = 24,\\ f^{(5)} = 0","explanation":"Every derivative after the fourth is 0."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_8c4effad9e1cb0', 'les_8a4cce987204b1', 'learn', 3, 'worked_example', '{"title":"Derivatives of $\\sin x$ repeat every 4","steps":[{"latex":"\\sin x \\to \\cos x \\to -\\sin x \\to -\\cos x \\to \\sin x","explanation":""},{"latex":"27 = 4 \\cdot 6 + 3 \\Rightarrow f^{(27)}(x) = -\\cos x","explanation":""}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_ffceaca4bbe2cc', 'les_8a4cce987204b1', 'learn', 4, 'worked_example', '{"title":"$s(t) = t^3 - 6t^2$ meters","steps":[{"latex":"v(t) = 3t^2 - 12t,\\ a(t) = 6t - 12","explanation":""},{"latex":"a(3) = 6 \\text{ m/s}^2","explanation":""}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_d3df92887596a3', 'les_8a4cce987204b1', 'experiment', 5, 'activity', '{"activity":"derivative-graph","title":"Read f″ from the slope of f′","params":{"fn":"quartic","a":0.8}}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_fa5c219544186b', 'les_8a4cce987204b1', 'experiment', 6, 'callout', '{"tone":"tip","title":"Try this","body":"Where the lower graph $f''$ is increasing, $f''''$ is positive and $f$ is concave up. Find the two points where $f''''(a) = 0$ for $\\frac{1}{4}x^4 - x^2$ (at $x = \\pm\\sqrt{2/3} \\approx \\pm 0.82$)."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_316041f8c41967', 'les_8a4cce987204b1', 'learn', 7, 'callout', '{"tone":"application","title":"Where this shows up","body":"Engineers limit \"jerk\", the third derivative of position, in elevators and trains because sudden changes in acceleration feel uncomfortable."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_eb9e338bed4d73', 'les_8a4cce987204b1', 1, 'practice', 'numeric', 1, 'If $f(x) = x^5$, find $f''''''(1)$.', '{"answer":60}', '[]', '$f'''''' = 60x^2$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_2927a394f3ee42', 'les_8a4cce987204b1', 2, 'practice', 'numeric', 2, 'If $f(x) = e^{2x}$, find $f''''(0)$.', '{"answer":4}', '[]', '$f'''' = 4e^{2x}$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_8c4effad9e1cb0', 'les_8a4cce987204b1', 3, 'practice', 'multiple_choice', 2, '$\frac{d^{30}}{dx^{30}}\cos x$ is…', '{"choices":["$\\cos x$","$-\\cos x$","$\\sin x$","$-\\sin x$"],"answer":1}', '["$30 = 4 \\cdot 7 + 2$."]', 'The second derivative of $\cos x$ is $-\cos x$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_ffceaca4bbe2cc', 'les_8a4cce987204b1', 4, 'review', 'numeric', 3, 'For $x^2 + y^2 = 25$, $y'''' = -\frac{25}{y^3}$. Find $y''''$ at $(0, 5)$.', '{"answer":-0.2,"tolerance":0.001}', '[]', '$-\frac{25}{125} = -0.2$: the top of the circle is concave down.');
INSERT OR IGNORE INTO concepts (id, subject_id, slug, name, description) VALUES ('cpt_36377b1d43a313', 'subj_math', 'derivatives', 'Derivatives', 'The instantaneous rate of change of a function; the slope of its tangent line.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_8a4cce987204b1', (SELECT id FROM concepts WHERE slug = 'derivatives'));
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_8a4cce987204b1', (SELECT id FROM concepts WHERE slug = 'concavity'));

-- Lesson: implicit-differentiation
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_78e867c5d3a356', 'implicit-differentiation', 'Implicit differentiation', 'Find dy/dx for curves defined by equations in x and y by differentiating both sides and treating y as a function of x.', 30, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_82624aa84d1342', 'les_78e867c5d3a356', 1, 'Differentiate terms involving y using the Chain Rule (dy/dx factor).');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_368b5368f4dbbf', 'les_78e867c5d3a356', 2, 'Solve for dy/dx and evaluate it at a point on the curve.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_f8f7fe0d4b9870', 'les_78e867c5d3a356', 3, 'Find horizontal and vertical tangents of implicitly defined curves.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_82624aa84d1342', 'les_78e867c5d3a356', 'learn', 1, 'definition', '{"term":"The method","body":"Differentiate both sides with respect to $x$. Each time you differentiate an expression in $y$, multiply by $\\frac{dy}{dx}$ (Chain Rule). Then collect the $\\frac{dy}{dx}$ terms and solve."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_368b5368f4dbbf', 'les_78e867c5d3a356', 'learn', 2, 'worked_example', '{"title":"The circle $x^2 + y^2 = 25$ at $(3, 4)$","steps":[{"latex":"2x + 2y\\frac{dy}{dx} = 0","explanation":""},{"latex":"\\frac{dy}{dx} = -\\frac{x}{y} = -\\frac{3}{4}","explanation":""}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_f8f7fe0d4b9870', 'les_78e867c5d3a356', 'learn', 3, 'worked_example', '{"title":"$x^3 + y^3 = 6xy$ at $(3, 3)$","steps":[{"latex":"3x^2 + 3y^2 y'' = 6y + 6xy''","explanation":"Product Rule on 6xy."},{"latex":"y''(3y^2 - 6x) = 6y - 3x^2","explanation":""},{"latex":"y''(27 - 18) = 18 - 27 \\Rightarrow y'' = -1","explanation":""}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_c70d8f92a9da02', 'les_78e867c5d3a356', 'experiment', 4, 'activity', '{"activity":"slope-field","title":"Circles hidden in dy/dx = −x/y","params":{"eq":"circle","x0":3,"y0":4}}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_426f7034c7ad60', 'les_78e867c5d3a356', 'experiment', 5, 'callout', '{"tone":"tip","title":"Try this","body":"The slope field of $\\frac{dy}{dx} = -\\frac{x}{y}$ is exactly the slope found implicitly from $x^2 + y^2 = r^2$. Each solution curve through a starting point is (half of) a circle."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_5acc7a10d81fdb', 'les_78e867c5d3a356', 'learn', 6, 'callout', '{"tone":"application","title":"Where this shows up","body":"Curves like orbits and level curves of a temperature map are often given by equations in $x$ and $y$ that can''t be solved for $y$; implicit differentiation still gives their slopes."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_82624aa84d1342', 'les_78e867c5d3a356', 1, 'practice', 'numeric', 1, 'For $xy = 6$, find $\frac{dy}{dx}$ at $(2, 3)$.', '{"answer":-1.5,"tolerance":0.001}', '[]', '$y + xy'' = 0 \Rightarrow y'' = -\frac{y}{x} = -1.5$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_368b5368f4dbbf', 'les_78e867c5d3a356', 2, 'practice', 'numeric', 2, 'For $x^2 + 3y^2 = 21$, find $\frac{dy}{dx}$ at $(3, 2)$.', '{"answer":-0.5,"tolerance":0.001}', '[]', '$2x + 6yy'' = 0 \Rightarrow y'' = -\frac{x}{3y} = -\frac{3}{6}$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_f8f7fe0d4b9870', 'les_78e867c5d3a356', 3, 'practice', 'multiple_choice', 2, '$\frac{d}{dx}(y^2)$ is…', '{"choices":["$2y$","$2y\\frac{dy}{dx}$","$2x$","$y^2\\frac{dy}{dx}$"],"answer":1}', '[]', 'Chain Rule: $y$ is a function of $x$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_c70d8f92a9da02', 'les_78e867c5d3a356', 4, 'review', 'multiple_choice', 3, 'On $x^2 + y^2 = 25$, where are the tangent lines vertical?', '{"choices":["(0, ±5)","(±5, 0)","(3, 4)","Nowhere"],"answer":1}', '[]', '$\frac{dy}{dx} = -\frac{x}{y}$ is undefined when $y = 0$ (and $x \ne 0$).');
INSERT OR IGNORE INTO concepts (id, subject_id, slug, name, description) VALUES ('cpt_36377b1d43a313', 'subj_math', 'derivatives', 'Derivatives', 'The instantaneous rate of change of a function; the slope of its tangent line.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_78e867c5d3a356', (SELECT id FROM concepts WHERE slug = 'derivatives'));
INSERT OR IGNORE INTO lesson_formulas (lesson_id, formula_id, position) VALUES ('les_78e867c5d3a356', (SELECT id FROM formulas WHERE slug = 'chain-rule'), 1);

-- Lesson: infinite-limits
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_0cafd7f2596c5d', 'infinite-limits', 'Infinite limits and vertical asymptotes', 'Describe unbounded behavior with infinite limits, determine the sign from each side, and connect infinite limits to vertical asymptotes.', 25, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_2547d46e7dd2d3', 'les_0cafd7f2596c5d', 1, 'Write and interpret lim f(x) = ±∞ as x approaches a.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_d47b94f91e6815', 'les_0cafd7f2596c5d', 2, 'Determine the sign of an infinite limit from each side using a sign analysis.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_5f1b585427bcbf', 'les_0cafd7f2596c5d', 3, 'Locate vertical asymptotes: x = a is one if either one-sided limit is infinite.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_2547d46e7dd2d3', 'les_0cafd7f2596c5d', 'learn', 1, 'definition', '{"term":"Infinite limit","body":"$\\lim_{x \\to a^+} f(x) = \\infty$ means $f(x)$ grows beyond any bound as $x$ approaches $a$ from the right. The limit does not exist as a number; $\\infty$ describes how it fails."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_d47b94f91e6815', 'les_0cafd7f2596c5d', 'learn', 2, 'definition', '{"term":"Vertical asymptote","body":"The line $x = a$ is a vertical asymptote if at least one one-sided limit of $f$ at $a$ is $\\infty$ or $-\\infty$."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_5f1b585427bcbf', 'les_0cafd7f2596c5d', 'learn', 3, 'worked_example', '{"title":"$\\lim_{x \\to 3^\\pm} \\dfrac{x + 1}{x - 3}$","steps":[{"latex":"x \\to 3^+: \\tfrac{4}{\\text{small positive}} \\to +\\infty","explanation":""},{"latex":"x \\to 3^-: \\tfrac{4}{\\text{small negative}} \\to -\\infty","explanation":""},{"latex":"\\text{vertical asymptote } x = 3","explanation":""}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_b4bf56d9bd0974', 'les_0cafd7f2596c5d', 'learn', 4, 'worked_example', '{"title":"Other common infinite limits","steps":[{"latex":"\\lim_{x \\to 0^+} \\ln x = -\\infty","explanation":""},{"latex":"\\lim_{x \\to \\pi/2^-} \\tan x = +\\infty","explanation":""}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_15268eb2b8929b', 'les_0cafd7f2596c5d', 'experiment', 5, 'activity', '{"activity":"rational-graph","title":"Approach the asymptote from each side","params":{"a":2,"h":1,"k":-1}}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_3f6b645b242d76', 'les_0cafd7f2596c5d', 'learn', 6, 'callout', '{"tone":"warning","title":"Check for holes","body":"$\\frac{x^2 - 1}{x - 1}$ is undefined at 1, but there''s no asymptote: it simplifies to $x + 1$. Asymptotes come from zeros of the denominator that don''t cancel."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_f2e82122d0e5da', 'les_0cafd7f2596c5d', 'learn', 7, 'callout', '{"tone":"application","title":"Where this shows up","body":"The cost of removing the last few percent of a pollutant often follows a model like $C(p) = \\frac{k p}{100 - p}$, which grows without bound as $p \\to 100^-$."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_2547d46e7dd2d3', 'les_0cafd7f2596c5d', 1, 'practice', 'multiple_choice', 1, '$\lim_{x \to 0^+} \dfrac{1}{x^2}$ is…', '{"choices":["0","1","$+\\infty$","$-\\infty$"],"answer":2}', '[]', 'The denominator is a small positive number.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_d47b94f91e6815', 'les_0cafd7f2596c5d', 2, 'practice', 'multiple_choice', 2, '$\lim_{x \to 2^-} \dfrac{3}{x - 2}$ is…', '{"choices":["$+\\infty$","$-\\infty$","0","3"],"answer":1}', '[]', '$x - 2$ is small and negative.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_5f1b585427bcbf', 'les_0cafd7f2596c5d', 3, 'practice', 'multiple_choice', 2, 'Where does $f(x) = \dfrac{x - 2}{x^2 - 4}$ have a vertical asymptote?', '{"choices":["x = 2 and x = −2","x = −2 only","x = 2 only","None"],"answer":1}', '[]', '$\frac{x - 2}{(x - 2)(x + 2)} = \frac{1}{x + 2}$: a hole at 2, an asymptote at −2.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_b4bf56d9bd0974', 'les_0cafd7f2596c5d', 4, 'review', 'multiple_choice', 3, '$\lim_{x \to 0^-} e^{1/x}$ is…', '{"choices":["0","1","$+\\infty$","$-\\infty$"],"answer":0}', '["What does $\\frac{1}{x}$ do as $x \\to 0^-$?"]', '$\frac{1}{x} \to -\infty$, so $e^{1/x} \to 0$. (From the right it goes to $+\infty$.)');
INSERT OR IGNORE INTO concepts (id, subject_id, slug, name, description) VALUES ('cpt_9523ccbcc4c521', 'subj_math', 'limits', 'Limits', 'The value a function''s outputs approach as the input approaches a given value.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_0cafd7f2596c5d', (SELECT id FROM concepts WHERE slug = 'limits'));

-- Lesson: intermediate-value-theorem
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_b1da59a4ed24aa', 'intermediate-value-theorem', 'The Intermediate Value Theorem', 'State the Intermediate Value Theorem, check its continuity hypothesis, and write complete justifications that a function takes a value or has a zero on an interval.', 25, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_74f1e37dc0371d', 'les_b1da59a4ed24aa', 1, 'State the IVT and its hypotheses.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_9ff9273e271585', 'les_b1da59a4ed24aa', 2, 'Use the IVT to guarantee a solution of f(x) = k on an interval.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_9589850453140d', 'les_b1da59a4ed24aa', 3, 'Write a complete AP-style justification.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_74f1e37dc0371d', 'les_b1da59a4ed24aa', 'learn', 1, 'definition', '{"term":"Intermediate Value Theorem","body":"If $f$ is continuous on $[a, b]$ and $k$ is any number between $f(a)$ and $f(b)$, then there is at least one $c$ in $(a, b)$ with $f(c) = k$."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_9ff9273e271585', 'les_b1da59a4ed24aa', 'learn', 2, 'worked_example', '{"title":"Show $f(x) = x^3 + x - 1$ has a zero in $(0, 1)$.","steps":[{"latex":"f \\text{ is a polynomial, so continuous on } [0, 1]","explanation":"State the hypothesis."},{"latex":"f(0) = -1 < 0 < 1 = f(1)","explanation":""},{"latex":"\\text{by the IVT, } f(c) = 0 \\text{ for some } c \\in (0, 1)","explanation":"Name the theorem in the conclusion."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_9589850453140d', 'les_b1da59a4ed24aa', 'learn', 3, 'worked_example', '{"title":"$f$ is continuous with $f(1) = 3$, $f(2) = -1$, $f(4) = 5$. How many zeros must $f$ have on $(1, 4)$?","steps":[{"latex":"3 \\to -1 \\text{ on } [1, 2]","explanation":"Sign change: at least one zero."},{"latex":"-1 \\to 5 \\text{ on } [2, 4]","explanation":"Another sign change."},{"latex":"\\text{at least 2}","explanation":"There could be more."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_47ef05a17e35ed', 'les_b1da59a4ed24aa', 'learn', 4, 'callout', '{"tone":"warning","title":"Continuity is required","body":"$f(x) = \\frac{1}{x}$ has $f(-1) = -1$ and $f(1) = 1$ but never equals 0: it isn''t continuous on $[-1, 1]$."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_64db928634e65e', 'les_b1da59a4ed24aa', 'learn', 5, 'callout', '{"tone":"application","title":"Where this shows up","body":"Root-finding algorithms like bisection rely on the IVT: if a continuous function changes sign on an interval, halve the interval and keep the half where the sign still changes."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_74f1e37dc0371d', 'les_b1da59a4ed24aa', 1, 'practice', 'multiple_choice', 1, 'Which hypothesis does the IVT require on $[a, b]$?', '{"choices":["f is differentiable","f is continuous","f is increasing","f(a) = f(b)"],"answer":1}', '[]', 'Continuity on the closed interval.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_9ff9273e271585', 'les_b1da59a4ed24aa', 2, 'practice', 'numeric', 2, '$g$ is continuous, $g(0) = 2$, $g(3) = 8$. The IVT guarantees $g(c) = k$ for some $c \in (0, 3)$ for which value: 1, 5, 9 or 10?', '{"answer":5}', '[]', 'Only 5 is between 2 and 8.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_9589850453140d', 'les_b1da59a4ed24aa', 3, 'practice', 'multiple_choice', 2, 'A continuous $h$ has $h(1) = 4$ and $h(5) = 4$. What does the IVT guarantee about zeros of $h$ on $(1, 5)$?', '{"choices":["At least one","Exactly one","Nothing","Exactly two"],"answer":2}', '[]', 'No sign change, so the IVT guarantees nothing (there might still be zeros).');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_47ef05a17e35ed', 'les_b1da59a4ed24aa', 4, 'review', 'multiple_choice', 3, 'Temperature at 6 a.m. was 50 °F and at noon 74 °F. Why must it have been 65 °F at some time between?', '{"choices":["Temperature is increasing","Temperature varies continuously with time, and 65 is between 50 and 74 (IVT)","The average is 62","It must have been"],"answer":1}', '[]', 'Continuity plus the IVT.');
INSERT OR IGNORE INTO concepts (id, subject_id, slug, name, description) VALUES ('cpt_1d074decbcdb94', 'subj_math', 'continuity', 'Continuity', 'A function is continuous at c when its limit at c exists and equals f(c).');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_b1da59a4ed24aa', (SELECT id FROM concepts WHERE slug = 'continuity'));

-- Lesson: inverse-function-derivatives
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_baa0ab489af90c', 'inverse-function-derivatives', 'Differentiating inverse functions', 'Find the derivative of an inverse function at a point with (f⁻¹)′(a) = 1/f′(f⁻¹(a)), using equations, tables and graphs.', 25, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_d3a93bd2cdf9e2', 'les_baa0ab489af90c', 1, 'Explain why the slope of an inverse is the reciprocal of the original slope at the reflected point.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_3c9307826b9b5e', 'les_baa0ab489af90c', 2, 'Compute (f⁻¹)′(a) without finding a formula for f⁻¹.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_52a8f604c6c2e5', 'les_baa0ab489af90c', 3, 'Use the result with tables of values.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_d3a93bd2cdf9e2', 'les_baa0ab489af90c', 'learn', 1, 'definition', '{"term":"Derivative of an inverse","body":"If $f$ is differentiable and one-to-one with $f''(f^{-1}(a)) \\ne 0$, then $(f^{-1})''(a) = \\frac{1}{f''(f^{-1}(a))}$. Reflecting across $y = x$ swaps rise and run, so slopes become reciprocals."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_3c9307826b9b5e', 'les_baa0ab489af90c', 'learn', 2, 'worked_example', '{"title":"$f(x) = x^3 + x$. Find $(f^{-1})''(2)$.","steps":[{"latex":"f(1) = 2 \\Rightarrow f^{-1}(2) = 1","explanation":"Find the matching input."},{"latex":"f''(x) = 3x^2 + 1,\\ f''(1) = 4","explanation":""},{"latex":"(f^{-1})''(2) = \\tfrac{1}{4}","explanation":"No formula for f⁻¹ needed."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_52a8f604c6c2e5', 'les_baa0ab489af90c', 'learn', 3, 'worked_example', '{"title":"Derivative of $\\ln x$ from $e^x$","steps":[{"latex":"y = \\ln x \\iff e^y = x","explanation":""},{"latex":"e^y y'' = 1 \\Rightarrow y'' = \\frac{1}{e^y} = \\frac{1}{x}","explanation":""}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_a8cbf54e4f8dc1', 'les_baa0ab489af90c', 'learn', 4, 'callout', '{"tone":"warning","title":"Evaluate at the right point","body":"Use $f''$ at $f^{-1}(a)$, not at $a$. In the example, $f''(2) = 13$ would give the wrong answer."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_b1df5bde297b5d', 'les_baa0ab489af90c', 'learn', 5, 'callout', '{"tone":"application","title":"Where this shows up","body":"If a thermometer''s reading is a known function of temperature, the inverse converts readings back to temperature, and its derivative tells how sensitive that conversion is."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_d3a93bd2cdf9e2', 'les_baa0ab489af90c', 1, 'practice', 'numeric', 1, '$f(2) = 5$ and $f''(2) = 4$. Find $(f^{-1})''(5)$.', '{"answer":0.25,"tolerance":0.001}', '[]', '$\frac{1}{f''(2)} = \frac{1}{4}$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_3c9307826b9b5e', 'les_baa0ab489af90c', 2, 'practice', 'numeric', 2, '$f(x) = 2x + \sin x$. Find $(f^{-1})''(0)$.', '{"answer":0.333,"tolerance":0.001}', '["$f(0) = 0$."]', '$f''(0) = 2 + \cos 0 = 3$, so $\frac{1}{3}$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_52a8f604c6c2e5', 'les_baa0ab489af90c', 3, 'practice', 'numeric', 2, '$f(x) = e^{x} + x$. Find $(f^{-1})''(1)$.', '{"answer":0.5,"tolerance":0.001}', '["$f(0) = 1$."]', '$f''(0) = e^0 + 1 = 2$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_a8cbf54e4f8dc1', 'les_baa0ab489af90c', 4, 'review', 'multiple_choice', 3, 'The graph of $f$ passes through $(1, 3)$ with slope 6 there. The graph of $f^{-1}$…', '{"choices":["passes through (1, 3) with slope 6","passes through (3, 1) with slope 1/6","passes through (3, 1) with slope 6","passes through (1, 3) with slope 1/6"],"answer":1}', '[]', 'Swap coordinates; take the reciprocal slope.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_baa0ab489af90c', (SELECT id FROM concepts WHERE slug = 'inverse-functions'));
INSERT OR IGNORE INTO concepts (id, subject_id, slug, name, description) VALUES ('cpt_36377b1d43a313', 'subj_math', 'derivatives', 'Derivatives', 'The instantaneous rate of change of a function; the slope of its tangent line.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_baa0ab489af90c', (SELECT id FROM concepts WHERE slug = 'derivatives'));
INSERT OR IGNORE INTO lesson_formulas (lesson_id, formula_id, position) VALUES ('les_baa0ab489af90c', (SELECT id FROM formulas WHERE slug = 'inverse-derivatives'), 1);

-- Lesson: inverse-trig-derivatives
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_c5ec616c453195', 'inverse-trig-derivatives', 'Differentiating inverse trigonometric functions', 'Derive and use the derivatives of arcsin x, arccos x and arctan x, combined with the Chain Rule.', 25, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_78c931b0adaf1d', 'les_c5ec616c453195', 1, 'Derive (arcsin x)′ = 1/√(1 − x²) with implicit differentiation.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_69119869380968', 'les_c5ec616c453195', 2, 'Use the derivatives of arcsin, arccos and arctan.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_9375b70fd59754', 'les_c5ec616c453195', 3, 'Combine them with the Chain Rule.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_78c931b0adaf1d', 'les_c5ec616c453195', 'learn', 1, 'worked_example', '{"title":"Derive $\\frac{d}{dx}\\arcsin x$","steps":[{"latex":"y = \\arcsin x \\iff \\sin y = x,\\ -\\tfrac{\\pi}{2} \\le y \\le \\tfrac{\\pi}{2}","explanation":""},{"latex":"\\cos y \\cdot y'' = 1 \\Rightarrow y'' = \\frac{1}{\\cos y}","explanation":""},{"latex":"\\cos y = \\sqrt{1 - x^2}","explanation":"cos y ≥ 0 on this interval."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_69119869380968', 'les_c5ec616c453195', 'learn', 2, 'definition', '{"term":"Derivatives","body":"$(\\arcsin x)'' = \\frac{1}{\\sqrt{1 - x^2}}$, $(\\arccos x)'' = -\\frac{1}{\\sqrt{1 - x^2}}$, $(\\arctan x)'' = \\frac{1}{1 + x^2}$."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_9375b70fd59754', 'les_c5ec616c453195', 'learn', 3, 'worked_example', '{"title":"With the Chain Rule","steps":[{"latex":"\\frac{d}{dx}\\arctan(2x) = \\frac{2}{1 + 4x^2}","explanation":""},{"latex":"\\frac{d}{dx}\\arcsin(x^2) = \\frac{2x}{\\sqrt{1 - x^4}}","explanation":""}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_fe9b1e2525965a', 'les_c5ec616c453195', 'learn', 4, 'callout', '{"tone":"application","title":"Where this shows up","body":"An observer watching a rocket rise from a distance $d$ sees it at angle $\\theta = \\arctan\\frac{h}{d}$; the rate the angle changes uses $(\\arctan u)''$."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_78c931b0adaf1d', 'les_c5ec616c453195', 1, 'practice', 'numeric', 1, 'Find the derivative of $\arctan x$ at $x = 1$.', '{"answer":0.5,"tolerance":0.001}', '[]', '$\frac{1}{1 + 1} = 0.5$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_69119869380968', 'les_c5ec616c453195', 2, 'practice', 'numeric', 1, 'Find the derivative of $\arccos x$ at $x = 0$.', '{"answer":-1}', '[]', '$-\frac{1}{\sqrt{1}} = -1$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_9375b70fd59754', 'les_c5ec616c453195', 3, 'practice', 'numeric', 2, 'Find $\frac{d}{dx}\arcsin\frac{x}{2}$ at $x = 1$, to three decimal places.', '{"answer":0.577,"tolerance":0.001}', '["Chain factor $\\frac{1}{2}$."]', '$\frac{1/2}{\sqrt{1 - 1/4}} = \frac{1}{\sqrt{3}} \approx 0.577$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_fe9b1e2525965a', 'les_c5ec616c453195', 4, 'review', 'multiple_choice', 3, 'What is the domain of $(\arcsin x)''$?', '{"choices":["$[-1, 1]$","$(-1, 1)$","All reals","$x \\ne 0$"],"answer":1}', '[]', 'At $x = \pm 1$ the denominator is 0.');
INSERT OR IGNORE INTO concepts (id, subject_id, slug, name, description) VALUES ('cpt_36377b1d43a313', 'subj_math', 'derivatives', 'Derivatives', 'The instantaneous rate of change of a function; the slope of its tangent line.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_c5ec616c453195', (SELECT id FROM concepts WHERE slug = 'derivatives'));
INSERT OR IGNORE INTO lesson_formulas (lesson_id, formula_id, position) VALUES ('les_c5ec616c453195', (SELECT id FROM formulas WHERE slug = 'inverse-derivatives'), 1);

-- Lesson: lhospitals-rule
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_5b5c09705a02a2', 'lhospitals-rule', 'Using L''Hospital''s Rule for determining limits of indeterminate forms', 'Evaluate 0/0 and ∞/∞ limits by differentiating numerator and denominator separately, check the hypotheses, and apply the rule repeatedly when needed.', 25, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_3ca495dc73f805', 'les_5b5c09705a02a2', 1, 'Confirm a limit has the form 0/0 or ∞/∞ before using the rule.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_7cd641d8caf7de', 'les_5b5c09705a02a2', 2, 'Apply lim f/g = lim f′/g′, repeating if needed.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_68a17078f4fa64', 'les_5b5c09705a02a2', 3, 'Avoid misusing the Quotient Rule or applying the rule to non-indeterminate forms.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_3ca495dc73f805', 'les_5b5c09705a02a2', 'learn', 1, 'definition', '{"term":"L''Hospital''s Rule","body":"If $\\lim f(x)$ and $\\lim g(x)$ are both 0, or both $\\pm\\infty$, and $f$ and $g$ are differentiable near the point with $g''(x) \\ne 0$, then $\\lim \\frac{f(x)}{g(x)} = \\lim \\frac{f''(x)}{g''(x)}$, provided the second limit exists (or is infinite)."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_7cd641d8caf7de', 'les_5b5c09705a02a2', 'learn', 2, 'worked_example', '{"title":"$\\lim_{x \\to 0} \\dfrac{e^x - 1}{x}$","steps":[{"latex":"\\tfrac{0}{0}","explanation":"Check the form."},{"latex":"\\lim_{x \\to 0} \\frac{e^x}{1} = 1","explanation":""}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_68a17078f4fa64', 'les_5b5c09705a02a2', 'learn', 3, 'worked_example', '{"title":"$\\lim_{x \\to \\infty} \\dfrac{x^2}{e^x}$","steps":[{"latex":"\\tfrac{\\infty}{\\infty} \\Rightarrow \\lim \\frac{2x}{e^x}","explanation":""},{"latex":"\\tfrac{\\infty}{\\infty} \\Rightarrow \\lim \\frac{2}{e^x} = 0","explanation":"Apply it again."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_194a94253cb41b', 'les_5b5c09705a02a2', 'learn', 4, 'worked_example', '{"title":"$\\lim_{x \\to 0} \\dfrac{1 - \\cos x}{x^2}$","steps":[{"latex":"\\tfrac{0}{0} \\Rightarrow \\lim \\frac{\\sin x}{2x}","explanation":""},{"latex":"\\tfrac{0}{0} \\Rightarrow \\lim \\frac{\\cos x}{2} = \\tfrac{1}{2}","explanation":""}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_d8ba509b365895', 'les_5b5c09705a02a2', 'learn', 5, 'callout', '{"tone":"warning","title":"Two common errors","body":"Differentiate the top and bottom separately: this is not the Quotient Rule. And don''t use it on $\\frac{\\sin x}{x + 1}$ as $x \\to 0$: that''s $\\frac{0}{1} = 0$, not indeterminate."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_1abdbe935ef306', 'les_5b5c09705a02a2', 'learn', 6, 'callout', '{"tone":"application","title":"Where this shows up","body":"Comparing growth rates, such as whether an algorithm''s running time $n\\log n$ grows slower than $n^{1.1}$, comes down to limits that L''Hospital''s Rule settles."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_3ca495dc73f805', 'les_5b5c09705a02a2', 1, 'practice', 'numeric', 1, 'Find $\lim_{x \to 0} \dfrac{e^{2x} - 1}{x}$.', '{"answer":2}', '[]', '$\frac{2e^{2x}}{1} \to 2$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_7cd641d8caf7de', 'les_5b5c09705a02a2', 2, 'practice', 'numeric', 2, 'Find $\lim_{x \to 1} \dfrac{\ln x}{x - 1}$.', '{"answer":1}', '[]', '$\frac{1/x}{1} \to 1$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_68a17078f4fa64', 'les_5b5c09705a02a2', 3, 'practice', 'numeric', 2, 'Find $\lim_{x \to \infty} \dfrac{\ln x}{x}$.', '{"answer":0}', '[]', '$\frac{1/x}{1} \to 0$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_194a94253cb41b', 'les_5b5c09705a02a2', 4, 'review', 'multiple_choice', 3, 'A student applies L''Hospital''s Rule to $\lim_{x \to 0} \frac{x + 1}{x + 2}$ and gets 1. What went wrong?', '{"choices":["Nothing; the answer is 1","The limit isn''t indeterminate; direct substitution gives 1/2","They should have used the Quotient Rule","The limit doesn''t exist"],"answer":1}', '[]', 'The rule applies only to 0/0 or ∞/∞.');
INSERT OR IGNORE INTO concepts (id, subject_id, slug, name, description) VALUES ('cpt_9523ccbcc4c521', 'subj_math', 'limits', 'Limits', 'The value a function''s outputs approach as the input approaches a given value.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_5b5c09705a02a2', (SELECT id FROM concepts WHERE slug = 'limits'));

-- Lesson: limit-definition-notation
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_d8975462a8a79d', 'limit-definition-notation', 'Defining limits and using limit notation', 'Understand the limit of f(x) as x approaches a as the value f(x) gets arbitrarily close to, read and write limit notation, and use one-sided limits to decide whether a limit exists.', 25, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_ac403d95d310cd', 'les_d8975462a8a79d', 1, 'Interpret lim f(x) = L as x → a in words and on a graph.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_1c417ccb5bc0ac', 'les_d8975462a8a79d', 2, 'Use one-sided limit notation and decide whether a two-sided limit exists.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_52c3a71bd62757', 'les_d8975462a8a79d', 3, 'Recognize that a limit depends on values near a, not at a.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_ac403d95d310cd', 'les_d8975462a8a79d', 'learn', 1, 'definition', '{"term":"Limit","body":"$\\lim_{x \\to a} f(x) = L$ means that $f(x)$ can be made as close to $L$ as we like by taking $x$ close enough to $a$ (but not equal to $a$). The value $f(a)$, if it exists, plays no role."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_1c417ccb5bc0ac', 'les_d8975462a8a79d', 'learn', 2, 'definition', '{"term":"One-sided limits","body":"$\\lim_{x \\to a^-} f(x)$ uses only $x < a$; $\\lim_{x \\to a^+} f(x)$ uses only $x > a$. The two-sided limit exists exactly when both one-sided limits exist and are equal."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_52c3a71bd62757', 'les_d8975462a8a79d', 'learn', 3, 'worked_example', '{"title":"$f(x) = \\dfrac{x^2 - 4}{x - 2}$ near $x = 2$","steps":[{"latex":"f(1.99) = 3.99,\\ f(2.01) = 4.01","explanation":"Values approach 4 from both sides."},{"latex":"\\lim_{x \\to 2} f(x) = 4","explanation":""},{"latex":"f(2) \\text{ is undefined}","explanation":"The limit exists anyway: limits are about nearby inputs."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_98622ec17feb6f', 'les_d8975462a8a79d', 'learn', 4, 'worked_example', '{"title":"$g(x) = 1$ for $x < 0$ and $g(x) = 3$ for $x \\ge 0$","steps":[{"latex":"\\lim_{x \\to 0^-} g(x) = 1,\\ \\lim_{x \\to 0^+} g(x) = 3","explanation":""},{"latex":"\\lim_{x \\to 0} g(x) \\text{ does not exist}","explanation":"The one-sided limits differ."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_6810dbc0b54046', 'les_d8975462a8a79d', 'learn', 5, 'callout', '{"tone":"note","title":"Three ways a limit can fail to exist","body":"The one-sided limits differ (a jump); the values grow without bound; or the values oscillate without settling, as $\\sin\\frac{1}{x}$ does near 0."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_dc2ccafe16673d', 'les_d8975462a8a79d', 'learn', 6, 'callout', '{"tone":"application","title":"Where this shows up","body":"Instantaneous speed is a limit: average speed over shorter and shorter time intervals. Limits are the foundation of every idea in calculus."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_ac403d95d310cd', 'les_d8975462a8a79d', 1, 'practice', 'numeric', 1, 'Find $\lim_{x \to 3} (2x + 1)$.', '{"answer":7}', '[]', 'The values approach $2(3) + 1 = 7$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_1c417ccb5bc0ac', 'les_d8975462a8a79d', 2, 'practice', 'multiple_choice', 2, '$f(5) = 2$, but $f(x)$ approaches 6 as $x$ approaches 5 from both sides. What is $\lim_{x \to 5} f(x)$?', '{"choices":["2","6","4","It doesn''t exist"],"answer":1}', '[]', 'The limit ignores the value at 5.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_52c3a71bd62757', 'les_d8975462a8a79d', 3, 'practice', 'multiple_choice', 2, '$\lim_{x \to 1^-} h(x) = 4$ and $\lim_{x \to 1^+} h(x) = 4$. Then $\lim_{x \to 1} h(x)$…', '{"choices":["equals 4","does not exist","equals h(1)","can''t be determined"],"answer":0}', '[]', 'Equal one-sided limits.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_98622ec17feb6f', 'les_d8975462a8a79d', 4, 'review', 'multiple_choice', 3, 'Which describes $\lim_{x \to 0} \sin\frac{1}{x}$?', '{"choices":["0","1","Does not exist: the values oscillate between −1 and 1","∞"],"answer":2}', '[]', 'As $x \to 0$, $\frac{1}{x}$ sweeps through infinitely many periods.');
INSERT OR IGNORE INTO concepts (id, subject_id, slug, name, description) VALUES ('cpt_9523ccbcc4c521', 'subj_math', 'limits', 'Limits', 'The value a function''s outputs approach as the input approaches a given value.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_d8975462a8a79d', (SELECT id FROM concepts WHERE slug = 'limits'));

-- Lesson: limits-at-infinity
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_949dc8ea5b3bdd', 'limits-at-infinity', 'Limits at infinity and horizontal asymptotes', 'Find limits as x → ±∞ by comparing dominant terms, handle radicals and exponentials, and identify horizontal asymptotes.', 25, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_123828b1a77506', 'les_949dc8ea5b3bdd', 1, 'Evaluate limits at infinity of rational functions by dividing by the highest power.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_72dda6cb68e11c', 'les_949dc8ea5b3bdd', 2, 'Handle square roots carefully when x → −∞.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_aabeaed7d81547', 'les_949dc8ea5b3bdd', 3, 'Use growth rates of exponential, polynomial and logarithmic functions.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_123828b1a77506', 'les_949dc8ea5b3bdd', 'learn', 1, 'definition', '{"term":"Horizontal asymptote","body":"If $\\lim_{x \\to \\infty} f(x) = L$ or $\\lim_{x \\to -\\infty} f(x) = L$, the line $y = L$ is a horizontal asymptote. A function can have different horizontal asymptotes in the two directions."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_72dda6cb68e11c', 'les_949dc8ea5b3bdd', 'learn', 2, 'worked_example', '{"title":"$\\lim_{x \\to \\infty} \\dfrac{3x^2 - x}{5x^2 + 2}$","steps":[{"latex":"\\frac{3 - 1/x}{5 + 2/x^2}","explanation":"Divide by x²."},{"latex":"\\to \\frac{3}{5} = 0.6","explanation":""}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_aabeaed7d81547', 'les_949dc8ea5b3bdd', 'learn', 3, 'worked_example', '{"title":"$\\lim_{x \\to -\\infty} \\dfrac{2x + 1}{\\sqrt{x^2 + 3}}$","steps":[{"latex":"\\sqrt{x^2} = |x| = -x \\text{ for } x < 0","explanation":""},{"latex":"\\frac{2x + 1}{-x\\sqrt{1 + 3/x^2}}","explanation":"Factor √(x²) = −x out of the root."},{"latex":"= \\frac{2 + 1/x}{-\\sqrt{1 + 3/x^2}} \\to -2","explanation":"Divide top and bottom by x."},{"latex":"\\text{as } x \\to +\\infty \\text{ the limit is } +2","explanation":"Two different horizontal asymptotes."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_0ebb7d128aec56', 'les_949dc8ea5b3bdd', 'learn', 4, 'definition', '{"term":"Growth rates","body":"As $x \\to \\infty$: $\\ln x$ grows slower than any positive power of $x$, which grows slower than $e^x$. So $\\frac{x^{10}}{e^x} \\to 0$ and $\\frac{\\ln x}{x} \\to 0$. Also $e^{-x} \\to 0$ and $\\arctan x \\to \\frac{\\pi}{2}$."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_300b7c1e38977d', 'les_949dc8ea5b3bdd', 'learn', 5, 'callout', '{"tone":"application","title":"Where this shows up","body":"Long-run behavior: a drug concentration $C(t) = \\frac{50t}{t^2 + 4}$ tends to 0, while a learning curve $\\frac{100t}{t + 5}$ levels off at 100."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_123828b1a77506', 'les_949dc8ea5b3bdd', 1, 'practice', 'numeric', 1, 'Find $\lim_{x \to \infty} \dfrac{7x^3 + 1}{2x^3 - x}$.', '{"answer":3.5,"tolerance":0.001}', '[]', 'Leading coefficients: $\frac{7}{2}$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_72dda6cb68e11c', 'les_949dc8ea5b3bdd', 2, 'practice', 'numeric', 2, 'Find $\lim_{x \to \infty} \dfrac{4x + 5}{x^2 + 1}$.', '{"answer":0}', '[]', 'Lower degree on top.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_aabeaed7d81547', 'les_949dc8ea5b3bdd', 3, 'practice', 'numeric', 2, 'Find $\lim_{x \to \infty} \dfrac{100t}{t + 5}$ (with $t$ in place of $x$).', '{"answer":100}', '[]', 'Divide by $t$: $\frac{100}{1 + 5/t} \to 100$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_0ebb7d128aec56', 'les_949dc8ea5b3bdd', 4, 'practice', 'multiple_choice', 2, '$\lim_{x \to \infty} \dfrac{x^5}{e^x}$ equals…', '{"choices":["∞","1","0","5"],"answer":2}', '[]', 'Exponentials outgrow polynomials.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_300b7c1e38977d', 'les_949dc8ea5b3bdd', 5, 'review', 'numeric', 3, 'Find $\lim_{x \to -\infty} \dfrac{3x}{\sqrt{4x^2 + 1}}$.', '{"answer":-1.5,"tolerance":0.001}', '["$\\sqrt{4x^2} = 2|x| = -2x$ for $x < 0$."]', '$\frac{3x}{-2x} = -1.5$.');
INSERT OR IGNORE INTO concepts (id, subject_id, slug, name, description) VALUES ('cpt_9523ccbcc4c521', 'subj_math', 'limits', 'Limits', 'The value a function''s outputs approach as the input approaches a given value.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_949dc8ea5b3bdd', (SELECT id FROM concepts WHERE slug = 'limits'));

-- Lesson: linearization
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_e75923434f7a48', 'linearization', 'Approximating values of a function using local linearity and linearization', 'Approximate function values near a point with the tangent line L(x) = f(a) + f′(a)(x − a), and use concavity to tell whether the estimate is too high or too low.', 25, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_b3e8efcf4791c7', 'les_e75923434f7a48', 1, 'Write the linearization of f at x = a.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_a60dcf94a33a21', 'les_e75923434f7a48', 2, 'Use it to approximate nearby values.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_f64897b00043bf', 'les_e75923434f7a48', 3, 'Decide whether the approximation is an overestimate or underestimate from concavity.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_b3e8efcf4791c7', 'les_e75923434f7a48', 'learn', 1, 'definition', '{"term":"Linearization","body":"$L(x) = f(a) + f''(a)(x - a)$ is the tangent line at $a$. Zoomed in near $a$, a differentiable function looks almost straight, so $f(x) \\approx L(x)$ for $x$ near $a$."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_a60dcf94a33a21', 'les_e75923434f7a48', 'learn', 2, 'worked_example', '{"title":"Approximate $\\sqrt{26}$","steps":[{"latex":"f(x) = \\sqrt{x},\\ a = 25","explanation":"Pick a nearby point where f is easy."},{"latex":"f(25) = 5,\\ f''(25) = \\tfrac{1}{2\\sqrt{25}} = \\tfrac{1}{10}","explanation":""},{"latex":"L(26) = 5 + \\tfrac{1}{10}(1) = 5.1","explanation":"Actual value: 5.0990…"},{"latex":"f'''' < 0 \\text{ (concave down)} \\Rightarrow \\text{overestimate}","explanation":"The tangent line lies above the curve."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_f64897b00043bf', 'les_e75923434f7a48', 'learn', 3, 'definition', '{"term":"Over or under?","body":"If $f$ is concave up near $a$, the tangent line lies below the graph: $L$ underestimates. Concave down: $L$ overestimates."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_9293fb9ee9950c', 'les_e75923434f7a48', 'experiment', 4, 'activity', '{"activity":"tangent-line","title":"Zoom in on a tangent line","params":{"fn":"x^2"}}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_064f7bafbec6e4', 'les_e75923434f7a48', 'experiment', 5, 'callout', '{"tone":"tip","title":"Try this","body":"Shrink $h$: near $a$ the curve and tangent line almost coincide. That closeness is local linearity."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_f2af43d3c0de60', 'les_e75923434f7a48', 'learn', 6, 'callout', '{"tone":"application","title":"Where this shows up","body":"Engineers use $\\sin\\theta \\approx \\theta$ (the linearization at 0) for small angles in pendulums and optics; financial analysts use linear approximations for small price changes."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_b3e8efcf4791c7', 'les_e75923434f7a48', 1, 'practice', 'numeric', 1, 'Use the linearization of $e^x$ at 0 to approximate $e^{0.1}$.', '{"answer":1.1,"tolerance":0.001}', '[]', '$L(x) = 1 + x$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_a60dcf94a33a21', 'les_e75923434f7a48', 2, 'practice', 'numeric', 2, 'Use the linearization of $x^{10}$ at $x = 1$ to approximate $(1.02)^{10}$.', '{"answer":1.2,"tolerance":0.001}', '[]', '$1 + 10(0.02) = 1.2$ (actual ≈ 1.219).');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_f64897b00043bf', 'les_e75923434f7a48', 3, 'practice', 'multiple_choice', 2, 'Is the estimate $(1.02)^{10} \approx 1.2$ too high or too low?', '{"choices":["Too high","Too low","Exact","Can''t tell"],"answer":1}', '["$f'''' = 90x^8 > 0$."]', 'Concave up: the tangent line underestimates.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_9293fb9ee9950c', 'les_e75923434f7a48', 4, 'review', 'numeric', 3, '$f(3) = 7$ and $f''(3) = -2$. Estimate $f(3.1)$.', '{"answer":6.8,"tolerance":0.001}', '[]', '$7 - 2(0.1) = 6.8$.');
INSERT OR IGNORE INTO concepts (id, subject_id, slug, name, description) VALUES ('cpt_36377b1d43a313', 'subj_math', 'derivatives', 'Derivatives', 'The instantaneous rate of change of a function; the slope of its tangent line.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_e75923434f7a48', (SELECT id FROM concepts WHERE slug = 'derivatives'));

-- Lesson: power-rule
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_af5c992f056f3a', 'power-rule', 'The Power Rule', 'Differentiate powers of x, including negative and fractional exponents, by rewriting radicals and reciprocals as powers first.', 20, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_592883eed262cf', 'les_af5c992f056f3a', 1, 'Apply d/dx xⁿ = nxⁿ⁻¹ for any real n.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_42087d0346b3b1', 'les_af5c992f056f3a', 2, 'Rewrite radicals and reciprocals as powers before differentiating.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_90e3396e3dc302', 'les_af5c992f056f3a', 3, 'Use the Power Rule to write tangent lines.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_592883eed262cf', 'les_af5c992f056f3a', 'learn', 1, 'definition', '{"term":"Power Rule","body":"$\\frac{d}{dx}x^n = nx^{n - 1}$ for every real number $n$ (where $x^n$ is defined and differentiable)."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_42087d0346b3b1', 'les_af5c992f056f3a', 'learn', 2, 'worked_example', '{"title":"Rewrite, then differentiate","steps":[{"latex":"\\frac{d}{dx}x^7 = 7x^6","explanation":""},{"latex":"\\frac{1}{x^3} = x^{-3} \\Rightarrow -3x^{-4}","explanation":""},{"latex":"\\sqrt{x} = x^{1/2} \\Rightarrow \\tfrac{1}{2}x^{-1/2}","explanation":""},{"latex":"x^{2/3} \\Rightarrow \\tfrac{2}{3}x^{-1/3}","explanation":""}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_90e3396e3dc302', 'les_af5c992f056f3a', 'learn', 3, 'worked_example', '{"title":"Tangent line to $y = \\sqrt{x}$ at $x = 4$","steps":[{"latex":"y(4) = 2,\\ y''(4) = \\tfrac{1}{2}(4)^{-1/2} = \\tfrac{1}{4}","explanation":""},{"latex":"y = 2 + \\tfrac{1}{4}(x - 4)","explanation":""}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_542065ebc05e47', 'les_af5c992f056f3a', 'learn', 4, 'callout', '{"tone":"warning","title":"Rewrite first","body":"$\\frac{1}{x^3}$ is not differentiated as $\\frac{1}{3x^2}$. Convert to $x^{-3}$ first."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_ba1e11620975df', 'les_af5c992f056f3a', 'learn', 5, 'callout', '{"tone":"application","title":"Where this shows up","body":"The area of a circle $A = \\pi r^2$ has $\\frac{dA}{dr} = 2\\pi r$, the circumference: a thin ring added to a circle has area about circumference × thickness."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_592883eed262cf', 'les_af5c992f056f3a', 1, 'practice', 'numeric', 1, 'If $f(x) = x^{-2}$, find $f''(1)$.', '{"answer":-2}', '[]', '$-2x^{-3}$ at 1 is $-2$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_42087d0346b3b1', 'les_af5c992f056f3a', 2, 'practice', 'numeric', 2, 'If $f(x) = \sqrt[3]{x}$, find $f''(8)$ to four decimal places.', '{"answer":0.0833,"tolerance":0.0001}', '[]', '$\frac{1}{3}8^{-2/3} = \frac{1}{12} \approx 0.0833$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_90e3396e3dc302', 'les_af5c992f056f3a', 3, 'practice', 'multiple_choice', 2, '$\frac{d}{dx}\frac{1}{\sqrt{x}}$ is…', '{"choices":["$\\frac{1}{2\\sqrt{x}}$","$-\\frac{1}{2}x^{-3/2}$","$-\\frac{1}{2}x^{-1/2}$","$\\frac{-1}{x}$"],"answer":1}', '[]', '$x^{-1/2} \Rightarrow -\frac{1}{2}x^{-3/2}$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_542065ebc05e47', 'les_af5c992f056f3a', 4, 'review', 'numeric', 3, 'Find the $y$-intercept of the tangent line to $y = \sqrt{x}$ at $x = 4$.', '{"answer":1}', '[]', '$y = 2 + \frac{1}{4}(x - 4) = \frac{1}{4}x + 1$.');
INSERT OR IGNORE INTO concepts (id, subject_id, slug, name, description) VALUES ('cpt_36377b1d43a313', 'subj_math', 'derivatives', 'Derivatives', 'The instantaneous rate of change of a function; the slope of its tangent line.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_af5c992f056f3a', (SELECT id FROM concepts WHERE slug = 'derivatives'));
INSERT OR IGNORE INTO lesson_formulas (lesson_id, formula_id, position) VALUES ('les_af5c992f056f3a', (SELECT id FROM formulas WHERE slug = 'power-rule'), 1);

-- Lesson: product-rule
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_3583aa9a515c77', 'product-rule', 'The Product Rule', 'Differentiate products of functions with (fg)′ = f′g + fg′, including from tables of values, and avoid the common mistake of multiplying derivatives.', 25, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_0d7e11fe64e0de', 'les_3583aa9a515c77', 1, 'Apply the Product Rule to products of two functions.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_5fa23cef918446', 'les_3583aa9a515c77', 2, 'Use the Product Rule with values from a table.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_c3666642e80ad3', 'les_3583aa9a515c77', 3, 'Explain why (fg)′ ≠ f′g′.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_0d7e11fe64e0de', 'les_3583aa9a515c77', 'learn', 1, 'definition', '{"term":"Product Rule","body":"$\\frac{d}{dx}[f(x)g(x)] = f''(x)g(x) + f(x)g''(x)$."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_5fa23cef918446', 'les_3583aa9a515c77', 'learn', 2, 'worked_example', '{"title":"$\\frac{d}{dx}\\left[x^2 \\sin x\\right]$","steps":[{"latex":"2x \\sin x + x^2 \\cos x","explanation":""}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_c3666642e80ad3', 'les_3583aa9a515c77', 'learn', 3, 'worked_example', '{"title":"Where does $y = xe^x$ have a horizontal tangent?","steps":[{"latex":"y'' = e^x + xe^x = e^x(1 + x)","explanation":""},{"latex":"e^x > 0 \\Rightarrow x = -1","explanation":""}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_bfe5b2e780e605', 'les_3583aa9a515c77', 'learn', 4, 'worked_example', '{"title":"$h(x) = f(x)g(x)$ with $f(2) = 3$, $f''(2) = -1$, $g(2) = 4$, $g''(2) = 5$","steps":[{"latex":"h''(2) = (-1)(4) + (3)(5) = 11","explanation":""}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_ba15a904dcf817', 'les_3583aa9a515c77', 'learn', 5, 'callout', '{"tone":"warning","title":"Not the product of derivatives","body":"For $x \\cdot x = x^2$, multiplying derivatives would give $1 \\cdot 1 = 1$, but the derivative is $2x$."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_44ccc62e9a3fbc', 'les_3583aa9a515c77', 'learn', 6, 'callout', '{"tone":"application","title":"Where this shows up","body":"Revenue = price × quantity. If both change over time, the rate of change of revenue uses the Product Rule."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_0d7e11fe64e0de', 'les_3583aa9a515c77', 1, 'practice', 'numeric', 1, 'Find $\frac{d}{dx}[x^3 \ln x]$ at $x = 1$.', '{"answer":1}', '[]', '$3x^2\ln x + x^2 = 0 + 1$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_5fa23cef918446', 'les_3583aa9a515c77', 2, 'practice', 'numeric', 2, 'Using the table values above, find $(fg)''(2)$ if instead $g''(2) = -2$.', '{"answer":-10}', '[]', '$(-1)(4) + 3(-2) = -10$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_c3666642e80ad3', 'les_3583aa9a515c77', 3, 'practice', 'multiple_choice', 2, '$\frac{d}{dx}[e^x \cos x]$ is…', '{"choices":["$-e^x \\sin x$","$e^x(\\cos x - \\sin x)$","$e^x(\\cos x + \\sin x)$","$e^x \\cos x$"],"answer":1}', '[]', '$e^x\cos x + e^x(-\sin x)$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_bfe5b2e780e605', 'les_3583aa9a515c77', 4, 'review', 'numeric', 3, 'A store''s price is $p = 20$ dollars, falling at 0.5 dollars per week; sales are $q = 300$ items per week, rising by 10 per week. How fast is revenue $pq$ changing, in dollars per week per week?', '{"answer":50,"unit":"dollars/week²"}', '[]', '$p''q + pq'' = (-0.5)(300) + (20)(10) = -150 + 200 = 50$.');
INSERT OR IGNORE INTO concepts (id, subject_id, slug, name, description) VALUES ('cpt_36377b1d43a313', 'subj_math', 'derivatives', 'Derivatives', 'The instantaneous rate of change of a function; the slope of its tangent line.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_3583aa9a515c77', (SELECT id FROM concepts WHERE slug = 'derivatives'));
INSERT OR IGNORE INTO lesson_formulas (lesson_id, formula_id, position) VALUES ('les_3583aa9a515c77', (SELECT id FROM formulas WHERE slug = 'derivative-rules'), 1);

-- Lesson: quotient-rule
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_a4d46b7319ccfa', 'quotient-rule', 'The Quotient Rule', 'Differentiate quotients with (f/g)′ = (f′g − fg′)/g², use it with tables, and know when rewriting is simpler.', 25, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_0ccc67d82608ba', 'les_a4d46b7319ccfa', 1, 'Apply the Quotient Rule in the correct order.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_823c55bf57b953', 'les_a4d46b7319ccfa', 2, 'Use the Quotient Rule with values from a table.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_9bc65c02a82893', 'les_a4d46b7319ccfa', 3, 'Recognize when rewriting a quotient avoids the rule entirely.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_0ccc67d82608ba', 'les_a4d46b7319ccfa', 'learn', 1, 'definition', '{"term":"Quotient Rule","body":"$\\frac{d}{dx}\\left[\\frac{f(x)}{g(x)}\\right] = \\frac{f''(x)g(x) - f(x)g''(x)}{[g(x)]^2}$, where $g(x) \\ne 0$. Memory aid: \"low d-high minus high d-low, over low squared.\""}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_823c55bf57b953', 'les_a4d46b7319ccfa', 'learn', 2, 'worked_example', '{"title":"$\\frac{d}{dx}\\dfrac{x^2 + 1}{x - 1}$","steps":[{"latex":"\\frac{2x(x - 1) - (x^2 + 1)(1)}{(x - 1)^2}","explanation":""},{"latex":"= \\frac{x^2 - 2x - 1}{(x - 1)^2}","explanation":""},{"latex":"\\text{at } x = 2: \\tfrac{4 - 4 - 1}{1} = -1","explanation":""}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_9bc65c02a82893', 'les_a4d46b7319ccfa', 'learn', 3, 'worked_example', '{"title":"When to rewrite instead: $\\dfrac{x^3 + 4}{x}$","steps":[{"latex":"= x^2 + 4x^{-1}","explanation":"Split the fraction."},{"latex":"\\Rightarrow 2x - 4x^{-2}","explanation":"No Quotient Rule needed."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_93105b0b46f68e', 'les_a4d46b7319ccfa', 'learn', 4, 'callout', '{"tone":"warning","title":"Order matters","body":"The numerator is $f''g - fg''$, with the minus sign. Swapping the order flips the sign of the answer."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_e1992020bc2ab8', 'les_a4d46b7319ccfa', 'learn', 5, 'callout', '{"tone":"application","title":"Where this shows up","body":"Average cost $\\frac{C(q)}{q}$ and concentration $\\frac{\\text{amount}}{\\text{volume}}$ are quotients; their rates of change come from the Quotient Rule."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_0ccc67d82608ba', 'les_a4d46b7319ccfa', 1, 'practice', 'numeric', 2, '$f(1) = 2$, $f''(1) = 3$, $g(1) = 4$, $g''(1) = -1$. Find $\left(\frac{f}{g}\right)''(1)$.', '{"answer":0.875,"tolerance":0.001}', '[]', '$\frac{3 \cdot 4 - 2(-1)}{16} = \frac{14}{16} = 0.875$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_823c55bf57b953', 'les_a4d46b7319ccfa', 2, 'practice', 'numeric', 2, 'Find $\frac{d}{dx}\dfrac{e^x}{x}$ at $x = 1$.', '{"answer":0}', '[]', '$\frac{e^x x - e^x}{x^2} = 0$ at 1.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_9bc65c02a82893', 'les_a4d46b7319ccfa', 3, 'practice', 'multiple_choice', 2, '$\frac{d}{dx}\dfrac{1}{g(x)}$ equals…', '{"choices":["$\\frac{1}{g''(x)}$","$-\\frac{g''(x)}{[g(x)]^2}$","$\\frac{g''(x)}{g(x)}$","$-\\frac{1}{[g(x)]^2}$"],"answer":1}', '[]', 'Quotient Rule with $f = 1$, $f'' = 0$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_93105b0b46f68e', 'les_a4d46b7319ccfa', 4, 'review', 'numeric', 3, 'Find $\frac{d}{dx}\dfrac{3x}{x^2 + 1}$ at $x = 0$.', '{"answer":3}', '[]', '$\frac{3(x^2 + 1) - 3x(2x)}{(x^2 + 1)^2} = 3$ at 0.');
INSERT OR IGNORE INTO concepts (id, subject_id, slug, name, description) VALUES ('cpt_36377b1d43a313', 'subj_math', 'derivatives', 'Derivatives', 'The instantaneous rate of change of a function; the slope of its tangent line.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_a4d46b7319ccfa', (SELECT id FROM concepts WHERE slug = 'derivatives'));
INSERT OR IGNORE INTO lesson_formulas (lesson_id, formula_id, position) VALUES ('les_a4d46b7319ccfa', (SELECT id FROM formulas WHERE slug = 'derivative-rules'), 1);

-- Lesson: related-rates-intro
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_7eb3b527152588', 'related-rates-intro', 'Introduction to related rates', 'Differentiate an equation relating several changing quantities with respect to time, and use one known rate to find another.', 25, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_cf15444883a457', 'les_7eb3b527152588', 1, 'Differentiate equations implicitly with respect to time t.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_f83323116a3955', 'les_7eb3b527152588', 2, 'Connect rates such as dA/dt and dr/dt through an equation.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_56460a43624750', 'les_7eb3b527152588', 3, 'Substitute values only after differentiating.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_cf15444883a457', 'les_7eb3b527152588', 'learn', 1, 'definition', '{"term":"The idea","body":"If quantities are linked by an equation and all change with time, differentiate both sides with respect to $t$. Each variable gets a rate: $\\frac{d}{dt}r^2 = 2r\\frac{dr}{dt}$."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_f83323116a3955', 'les_7eb3b527152588', 'learn', 2, 'worked_example', '{"title":"A ripple''s radius grows at 2 cm/s. How fast is its area growing when $r = 5$ cm?","steps":[{"latex":"A = \\pi r^2","explanation":""},{"latex":"\\frac{dA}{dt} = 2\\pi r\\frac{dr}{dt}","explanation":"Differentiate with respect to t."},{"latex":"= 2\\pi(5)(2) = 20\\pi \\approx 62.8 \\text{ cm}^2\\text{/s}","explanation":"Substitute last."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_56460a43624750', 'les_7eb3b527152588', 'learn', 3, 'callout', '{"tone":"warning","title":"Differentiate before substituting","body":"If you plug in $r = 5$ first, $A = 25\\pi$ is a constant and its derivative is 0. Values that change must stay variables until after differentiating."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_4baffbd8174545', 'les_7eb3b527152588', 'learn', 4, 'callout', '{"tone":"application","title":"Where this shows up","body":"Air traffic controllers compute how fast the distance between two planes is changing from each plane''s speed: a related-rates calculation."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_cf15444883a457', 'les_7eb3b527152588', 1, 'practice', 'numeric', 2, 'A balloon''s radius grows at 0.5 cm/s. How fast is its volume growing, in cm³/s, when $r = 3$ cm? ($V = \frac{4}{3}\pi r^3$.) Round to two decimal places.', '{"answer":56.55,"tolerance":0.02,"unit":"cm³/s"}', '[]', '$4\pi r^2 \frac{dr}{dt} = 4\pi(9)(0.5) = 18\pi \approx 56.55$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_f83323116a3955', 'les_7eb3b527152588', 2, 'practice', 'numeric', 2, 'A square''s side grows at 3 cm/min. How fast is the area growing when the side is 10 cm, in cm²/min?', '{"answer":60,"unit":"cm²/min"}', '[]', '$\frac{dA}{dt} = 2s\frac{ds}{dt} = 60$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_56460a43624750', 'les_7eb3b527152588', 3, 'practice', 'multiple_choice', 2, 'Differentiating $x^2 + y^2 = 25$ with respect to $t$ gives…', '{"choices":["$2x + 2y = 0$","$2x\\frac{dx}{dt} + 2y\\frac{dy}{dt} = 0$","$\\frac{dy}{dx} = -\\frac{x}{y}$","$2x\\frac{dx}{dt} = 25$"],"answer":1}', '[]', 'Each variable depends on $t$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_4baffbd8174545', 'les_7eb3b527152588', 4, 'review', 'numeric', 3, 'A circle''s area grows at $12\pi$ cm²/s. How fast is the radius growing when $r = 3$ cm, in cm/s?', '{"answer":2,"unit":"cm/s"}', '[]', '$12\pi = 2\pi(3)\frac{dr}{dt}$, so $\frac{dr}{dt} = 2$.');
INSERT OR IGNORE INTO concepts (id, subject_id, slug, name, description) VALUES ('cpt_bd25603003c77f', 'subj_math', 'related-rates', 'Related rates', 'Finding how fast one quantity changes from how fast related quantities change.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_7eb3b527152588', (SELECT id FROM concepts WHERE slug = 'related-rates'));
INSERT OR IGNORE INTO lesson_formulas (lesson_id, formula_id, position) VALUES ('les_7eb3b527152588', (SELECT id FROM formulas WHERE slug = 'chain-rule'), 1);

-- Lesson: removing-discontinuities
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_118c0191e335ed', 'removing-discontinuities', 'Removing discontinuities', 'Recognize removable discontinuities, where the limit exists but the function is undefined or has the wrong value, and redefine the function at one point to make it continuous.', 20, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_c3abf6cb13c5f4', 'les_118c0191e335ed', 1, 'Identify a removable discontinuity by checking that the limit exists.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_757e43b1fc3e0f', 'les_118c0191e335ed', 2, 'Redefine a function at a point to remove a discontinuity.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_f67599a22159a1', 'les_118c0191e335ed', 3, 'Explain why jump and infinite discontinuities can''t be removed.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_c3abf6cb13c5f4', 'les_118c0191e335ed', 'learn', 1, 'definition', '{"term":"Removable discontinuity","body":"A discontinuity at $c$ is removable if $\\lim_{x \\to c} f(x)$ exists. Defining (or redefining) $f(c)$ to equal that limit makes $f$ continuous at $c$."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_757e43b1fc3e0f', 'les_118c0191e335ed', 'learn', 2, 'worked_example', '{"title":"Remove the discontinuity of $g(x) = \\dfrac{x^2 - 9}{x - 3}$","steps":[{"latex":"\\lim_{x \\to 3} g(x) = \\lim_{x \\to 3} (x + 3) = 6","explanation":""},{"latex":"\\text{define } g(3) = 6","explanation":"Now g equals x + 3 everywhere."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_f67599a22159a1', 'les_118c0191e335ed', 'learn', 3, 'worked_example', '{"title":"$f(x) = \\dfrac{\\sin x}{x}$ is undefined at 0","steps":[{"latex":"\\lim_{x \\to 0} \\frac{\\sin x}{x} = 1","explanation":""},{"latex":"\\text{define } f(0) = 1","explanation":"The extended function is continuous everywhere."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_cc35b4a62d6f2e', 'les_118c0191e335ed', 'learn', 4, 'callout', '{"tone":"warning","title":"Not every discontinuity is removable","body":"At a jump the one-sided limits differ, and at a vertical asymptote the function is unbounded. No single value fixes either one."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_d7544941c2c696', 'les_118c0191e335ed', 'learn', 5, 'callout', '{"tone":"application","title":"Where this shows up","body":"The function $\\frac{\\sin x}{x}$, extended with value 1 at 0, is the \"sinc\" function used in signal processing."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_c3abf6cb13c5f4', 'les_118c0191e335ed', 1, 'practice', 'numeric', 1, 'What value should $h(5)$ have so $h(x) = \dfrac{x^2 - 25}{x - 5}$ is continuous at 5?', '{"answer":10}', '[]', '$x + 5 \to 10$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_757e43b1fc3e0f', 'les_118c0191e335ed', 2, 'practice', 'numeric', 2, 'What value makes $f(x) = \dfrac{\sqrt{x + 4} - 2}{x}$ continuous at 0? Give a decimal.', '{"answer":0.25,"tolerance":0.001}', '["Rationalize."]', '$\frac{1}{\sqrt{x + 4} + 2} \to \frac{1}{4}$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_f67599a22159a1', 'les_118c0191e335ed', 3, 'practice', 'multiple_choice', 2, 'Which discontinuity is removable?', '{"choices":["$\\frac{1}{x}$ at 0","$\\frac{x^2 - x}{x}$ at 0","$\\frac{|x|}{x}$ at 0","$\\tan x$ at $\\frac{\\pi}{2}$"],"answer":1}', '[]', '$\frac{x^2 - x}{x} = x - 1$ for $x \ne 0$; the limit is −1.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_cc35b4a62d6f2e', 'les_118c0191e335ed', 4, 'review', 'multiple_choice', 3, '$\lim_{x \to 2^-} f(x) = 1$, $\lim_{x \to 2^+} f(x) = 5$. Can redefining $f(2)$ make $f$ continuous at 2?', '{"choices":["Yes, set f(2) = 3","Yes, set f(2) = 1","No: the two-sided limit doesn''t exist","Yes, set f(2) = 5"],"answer":2}', '[]', 'A jump can''t be removed.');
INSERT OR IGNORE INTO concepts (id, subject_id, slug, name, description) VALUES ('cpt_1d074decbcdb94', 'subj_math', 'continuity', 'Continuity', 'A function is continuous at c when its limit at c exists and equals f(c).');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_118c0191e335ed', (SELECT id FROM concepts WHERE slug = 'continuity'));

-- Lesson: selecting-derivative-procedures
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_3c33aaf48f0431', 'selecting-derivative-procedures', 'Selecting procedures for calculating derivatives', 'Plan a derivative before computing it: simplify first, identify the outermost structure, and apply product, quotient and chain rules in the right order.', 25, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_b1215928cb9d9d', 'les_3c33aaf48f0431', 1, 'Identify the outermost operation (sum, product, quotient or composition).');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_6f057d37250617', 'les_3c33aaf48f0431', 2, 'Simplify or rewrite expressions before differentiating when it helps.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_242c9874f57a20', 'les_3c33aaf48f0431', 3, 'Combine rules correctly in multi-step derivatives.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_b1215928cb9d9d', 'les_3c33aaf48f0431', 'learn', 1, 'definition', '{"term":"A plan","body":"1. Can you rewrite it simpler (split a fraction, use log properties, negative exponents)? 2. What''s the last operation you''d do to compute it? That''s the outermost rule. 3. Work inward, applying the Chain Rule at each layer."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_6f057d37250617', 'les_3c33aaf48f0431', 'learn', 2, 'worked_example', '{"title":"$f(x) = x^2 e^{3x}$","steps":[{"latex":"\\text{outermost: product}","explanation":""},{"latex":"2x e^{3x} + x^2 \\cdot 3e^{3x}","explanation":"Chain Rule inside the second term."},{"latex":"= xe^{3x}(2 + 3x)","explanation":""}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_242c9874f57a20', 'les_3c33aaf48f0431', 'learn', 3, 'worked_example', '{"title":"$g(x) = \\ln\\dfrac{x^2}{\\sqrt{x + 1}}$","steps":[{"latex":"= 2\\ln x - \\tfrac{1}{2}\\ln(x + 1)","explanation":"Log properties first."},{"latex":"g''(x) = \\frac{2}{x} - \\frac{1}{2(x + 1)}","explanation":"Much easier than the Quotient Rule inside a log."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_8ee20dd76deb1e', 'les_3c33aaf48f0431', 'learn', 4, 'callout', '{"tone":"tip","title":"Check the structure","body":"$\\sin^2 x$ means $(\\sin x)^2$ (power outside), while $\\sin(x^2)$ has the power inside. Their derivatives are $2\\sin x\\cos x$ and $2x\\cos(x^2)$."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_dc42e2cefd64e5', 'les_3c33aaf48f0431', 'learn', 5, 'callout', '{"tone":"application","title":"Where this shows up","body":"Real models combine pieces: a damped vibration $e^{-0.1t}\\cos(2t)$ needs both the Product and Chain Rules to find its velocity."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_b1215928cb9d9d', 'les_3c33aaf48f0431', 1, 'practice', 'numeric', 1, 'Find $\frac{d}{dx}\ln(x^2 + 1)$ at $x = 1$.', '{"answer":1}', '[]', '$\frac{2x}{x^2 + 1} = 1$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_6f057d37250617', 'les_3c33aaf48f0431', 2, 'practice', 'numeric', 2, 'Find $\frac{d}{dx}\sin^2 x$ at $x = \frac{\pi}{4}$.', '{"answer":1,"tolerance":0.001}', '[]', '$2\sin x\cos x = \sin 2x = 1$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_242c9874f57a20', 'les_3c33aaf48f0431', 3, 'practice', 'numeric', 2, 'Find $\frac{d}{dt}\left[e^{-0.1t}\cos 2t\right]$ at $t = 0$.', '{"answer":-0.1,"tolerance":0.001}', '[]', '$-0.1e^{-0.1t}\cos 2t - 2e^{-0.1t}\sin 2t = -0.1$ at 0.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_8ee20dd76deb1e', 'les_3c33aaf48f0431', 4, 'review', 'multiple_choice', 3, 'What is the outermost rule for $\dfrac{x}{(x^2 + 1)^3}$?', '{"choices":["Chain Rule","Quotient Rule (or Product Rule with a negative power)","Power Rule","Sum Rule"],"answer":1}', '[]', 'It''s a quotient; the Chain Rule appears inside for $(x^2 + 1)^3$.');
INSERT OR IGNORE INTO concepts (id, subject_id, slug, name, description) VALUES ('cpt_36377b1d43a313', 'subj_math', 'derivatives', 'Derivatives', 'The instantaneous rate of change of a function; the slope of its tangent line.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_3c33aaf48f0431', (SELECT id FROM concepts WHERE slug = 'derivatives'));
INSERT OR IGNORE INTO lesson_formulas (lesson_id, formula_id, position) VALUES ('les_3c33aaf48f0431', (SELECT id FROM formulas WHERE slug = 'derivative-rules'), 1);
INSERT OR IGNORE INTO lesson_formulas (lesson_id, formula_id, position) VALUES ('les_3c33aaf48f0431', (SELECT id FROM formulas WHERE slug = 'chain-rule'), 2);

-- Lesson: selecting-limit-procedures
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_b2b946ded5106e', 'selecting-limit-procedures', 'Selecting procedures for determining limits', 'Choose an efficient method for a limit: direct substitution, factoring, rationalizing, trig identities and special limits, or one-sided sign analysis, based on what substitution produces.', 25, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_0dc106bff6c824', 'les_b2b946ded5106e', 1, 'Start every limit by trying direct substitution.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_530bd1c83f3170', 'les_b2b946ded5106e', 2, 'Recognize 0/0 as a signal to rewrite, and nonzero/0 as a signal for an infinite limit.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_b52b773cf171bb', 'les_b2b946ded5106e', 3, 'Choose factoring, rationalizing or special trig limits to rewrite 0/0 forms.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_0dc106bff6c824', 'les_b2b946ded5106e', 'learn', 1, 'definition', '{"term":"Decision steps","body":"1. Substitute. If you get a number, that''s the limit (for continuous functions). 2. If you get $\\frac{0}{0}$, rewrite: factor and cancel, rationalize, combine fractions, or use $\\frac{\\sin x}{x} \\to 1$. 3. If you get $\\frac{\\text{nonzero}}{0}$, the limit is infinite or doesn''t exist; check signs from each side."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_530bd1c83f3170', 'les_b2b946ded5106e', 'learn', 2, 'worked_example', '{"title":"$\\lim_{x \\to 9} \\dfrac{\\sqrt{x} - 3}{x - 9}$","steps":[{"latex":"\\tfrac{0}{0}","explanation":"Rewrite. Note x − 9 = (√x − 3)(√x + 3)."},{"latex":"\\frac{1}{\\sqrt{x} + 3} \\to \\frac{1}{6}","explanation":""}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_b52b773cf171bb', 'les_b2b946ded5106e', 'learn', 3, 'worked_example', '{"title":"$\\lim_{x \\to 0} \\dfrac{\\sin 3x}{x}$","steps":[{"latex":"\\frac{\\sin 3x}{x} = 3 \\cdot \\frac{\\sin 3x}{3x}","explanation":"Match the special limit."},{"latex":"3 \\cdot 1 = 3","explanation":""}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_024caccbc719e0', 'les_b2b946ded5106e', 'learn', 4, 'worked_example', '{"title":"$\\lim_{x \\to 1} \\dfrac{x + 2}{(x - 1)^2}$","steps":[{"latex":"\\tfrac{3}{0}","explanation":"Nonzero over zero."},{"latex":"(x - 1)^2 > 0 \\text{ on both sides}","explanation":""},{"latex":"+\\infty","explanation":"The limit is infinite (it doesn''t exist as a number)."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_27975d558b3671', 'les_b2b946ded5106e', 'learn', 5, 'callout', '{"tone":"warning","title":"0/0 is not an answer","body":"$\\frac{0}{0}$ is called an indeterminate form: the limit could be anything. It tells you to do more work, not that the limit fails to exist."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_1bc094a9863ec4', 'les_b2b946ded5106e', 'learn', 6, 'callout', '{"tone":"application","title":"Where this shows up","body":"Every derivative from the definition is a 0/0 limit, so these rewriting skills are used constantly in the rest of the course."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_0dc106bff6c824', 'les_b2b946ded5106e', 1, 'practice', 'numeric', 1, 'Find $\lim_{x \to 2} (x^3 - x)$.', '{"answer":6}', '[]', 'Substitute: $8 - 2 = 6$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_530bd1c83f3170', 'les_b2b946ded5106e', 2, 'practice', 'numeric', 2, 'Find $\lim_{x \to -3} \dfrac{x^2 - 9}{x + 3}$.', '{"answer":-6}', '[]', '$\frac{(x - 3)(x + 3)}{x + 3} = x - 3 \to -6$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_b52b773cf171bb', 'les_b2b946ded5106e', 3, 'practice', 'numeric', 2, 'Find $\lim_{x \to 0} \dfrac{\sin 5x}{2x}$.', '{"answer":2.5,"tolerance":0.001}', '[]', '$\frac{5}{2} \cdot \frac{\sin 5x}{5x} \to 2.5$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_024caccbc719e0', 'les_b2b946ded5106e', 4, 'practice', 'numeric', 2, 'Find $\lim_{x \to 4} \dfrac{x - 4}{\sqrt{x} - 2}$.', '{"answer":4}', '["$x - 4 = (\\sqrt{x} - 2)(\\sqrt{x} + 2)$."]', '$\sqrt{x} + 2 \to 4$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_27975d558b3671', 'les_b2b946ded5106e', 5, 'review', 'multiple_choice', 3, 'Substituting into $\lim_{x \to 2} \frac{x + 1}{x - 2}$ gives $\frac{3}{0}$. What can you conclude?', '{"choices":["The limit is 0","The limit is infinite or does not exist; check one-sided signs","The limit is 3","Factor and cancel"],"answer":1}', '[]', 'From the right it goes to $+\infty$, from the left to $-\infty$, so the two-sided limit does not exist.');
INSERT OR IGNORE INTO concepts (id, subject_id, slug, name, description) VALUES ('cpt_9523ccbcc4c521', 'subj_math', 'limits', 'Limits', 'The value a function''s outputs approach as the input approaches a given value.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_b2b946ded5106e', (SELECT id FROM concepts WHERE slug = 'limits'));
INSERT OR IGNORE INTO lesson_formulas (lesson_id, formula_id, position) VALUES ('les_b2b946ded5106e', (SELECT id FROM formulas WHERE slug = 'special-trig-limits'), 1);

-- Lesson: solving-related-rates
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_343bdff49f6db0', 'solving-related-rates', 'Solving related rates problems', 'Solve multi-step related rates problems: draw and label a diagram, write an equation, eliminate extra variables with geometry, differentiate, and substitute.', 35, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_c5eca07cdf7fe6', 'les_343bdff49f6db0', 1, 'Follow a reliable sequence: diagram, knowns and unknown, equation, differentiate, substitute.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_8b4c576ee4bae8', 'les_343bdff49f6db0', 2, 'Use similar triangles to eliminate a variable before differentiating.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_cc9f212431dedb', 'les_343bdff49f6db0', 3, 'Interpret the sign of the answer.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_c5eca07cdf7fe6', 'les_343bdff49f6db0', 'learn', 1, 'definition', '{"term":"Steps","body":"1. Draw and label the changing quantities as variables. 2. List the given rate(s) and the rate you want, at the given instant. 3. Write an equation relating the variables (eliminate extras if needed). 4. Differentiate with respect to $t$. 5. Substitute the instant''s values and solve."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_8b4c576ee4bae8', 'les_343bdff49f6db0', 'learn', 2, 'figure', '{"src":"/figures/sliding-ladder.svg","alt":"A 10-foot ladder leans against a wall. Its foot is x feet from the wall and slides away at 1 foot per second; its top is y feet up the wall and slides down at an unknown rate. The sides satisfy x squared plus y squared equals 100.","caption":"Label what changes as variables; only the ladder''s length stays fixed."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_cc9f212431dedb', 'les_343bdff49f6db0', 'learn', 3, 'worked_example', '{"title":"The ladder''s foot slides away at 1 ft/s. How fast is the top sliding down when the foot is 6 ft from the wall?","steps":[{"latex":"x^2 + y^2 = 100","explanation":""},{"latex":"2x\\frac{dx}{dt} + 2y\\frac{dy}{dt} = 0","explanation":""},{"latex":"x = 6 \\Rightarrow y = 8","explanation":"Find the other variable at that instant."},{"latex":"6(1) + 8\\frac{dy}{dt} = 0 \\Rightarrow \\frac{dy}{dt} = -0.75","explanation":"The top slides down at 0.75 ft/s."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_83fb9053de9219', 'les_343bdff49f6db0', 'learn', 4, 'worked_example', '{"title":"Water fills an inverted cone (radius 3 ft, height 6 ft) at 2 ft³/min. How fast is the depth rising when it''s 3 ft deep?","steps":[{"latex":"\\frac{r}{h} = \\frac{3}{6} \\Rightarrow r = \\frac{h}{2}","explanation":"Similar triangles."},{"latex":"V = \\frac{1}{3}\\pi r^2 h = \\frac{\\pi h^3}{12}","explanation":""},{"latex":"\\frac{dV}{dt} = \\frac{\\pi h^2}{4}\\frac{dh}{dt}","explanation":""},{"latex":"2 = \\frac{9\\pi}{4}\\frac{dh}{dt} \\Rightarrow \\frac{dh}{dt} = \\frac{8}{9\\pi} \\approx 0.283","explanation":"ft/min"}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_d00394dcb7a18a', 'les_343bdff49f6db0', 'learn', 5, 'callout', '{"tone":"application","title":"Where this shows up","body":"Reservoir engineers convert inflow (volume per minute) into how fast the water level rises, which depends on the reservoir''s shape at that depth."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_c5eca07cdf7fe6', 'les_343bdff49f6db0', 1, 'practice', 'numeric', 2, 'For the ladder, how fast is the top sliding down when the foot is 8 ft from the wall, in ft/s? Give a positive number.', '{"answer":1.333,"tolerance":0.002,"unit":"ft/s"}', '["Then $y = 6$."]', '$8(1) + 6\frac{dy}{dt} = 0 \Rightarrow \frac{dy}{dt} = -\frac{4}{3}$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_8b4c576ee4bae8', 'les_343bdff49f6db0', 2, 'practice', 'numeric', 2, 'Car A drives north at 30 mph and car B east at 40 mph from the same point. How fast is the distance between them growing, in mph?', '{"answer":50,"unit":"mph"}', '["After $t$ hours the legs are $30t$ and $40t$."]', '$D = 50t$, so $\frac{dD}{dt} = 50$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_cc9f212431dedb', 'les_343bdff49f6db0', 3, 'practice', 'multiple_choice', 2, 'In the cone problem, why substitute $r = \frac{h}{2}$ before differentiating?', '{"choices":["To make the answer positive","So V depends on one variable whose rate we want","Because r is constant","It''s optional and changes nothing"],"answer":1}', '[]', 'Otherwise you''d also need $\frac{dr}{dt}$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_83fb9053de9219', 'les_343bdff49f6db0', 4, 'review', 'numeric', 3, 'For the cone, how fast is the depth rising when the water is 2 ft deep, in ft/min? Round to three decimal places.', '{"answer":0.637,"tolerance":0.002,"unit":"ft/min"}', '[]', '$2 = \frac{\pi(4)}{4}\frac{dh}{dt} \Rightarrow \frac{dh}{dt} = \frac{2}{\pi} \approx 0.637$.');
INSERT OR IGNORE INTO concepts (id, subject_id, slug, name, description) VALUES ('cpt_bd25603003c77f', 'subj_math', 'related-rates', 'Related rates', 'Finding how fast one quantity changes from how fast related quantities change.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_343bdff49f6db0', (SELECT id FROM concepts WHERE slug = 'related-rates'));
INSERT OR IGNORE INTO lesson_formulas (lesson_id, formula_id, position) VALUES ('les_343bdff49f6db0', (SELECT id FROM formulas WHERE slug = 'chain-rule'), 1);

-- Lesson: squeeze-theorem
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_467b75bfe24e34', 'squeeze-theorem', 'The Squeeze Theorem', 'Find limits of functions trapped between two functions with the same limit, and use the theorem to establish the special limit sin x / x → 1.', 25, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_97992df48bc350', 'les_467b75bfe24e34', 1, 'State the Squeeze Theorem and its conditions.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_095f404b26f981', 'les_467b75bfe24e34', 2, 'Find bounding functions using −1 ≤ sin θ ≤ 1 and −1 ≤ cos θ ≤ 1.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_937f643ac11562', 'les_467b75bfe24e34', 3, 'Apply lim sin x / x = 1 to related limits.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_97992df48bc350', 'les_467b75bfe24e34', 'learn', 1, 'definition', '{"term":"Squeeze Theorem","body":"If $g(x) \\le f(x) \\le h(x)$ for all $x$ near $c$ (except possibly at $c$), and $\\lim_{x \\to c} g(x) = \\lim_{x \\to c} h(x) = L$, then $\\lim_{x \\to c} f(x) = L$."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_095f404b26f981', 'les_467b75bfe24e34', 'learn', 2, 'figure', '{"src":"/figures/squeeze-theorem.svg","alt":"The graph of x squared times sine of one over x oscillates faster and faster near zero, but always stays between the dashed parabolas y = x squared and y = negative x squared, which both pass through the origin.","caption":"Squeezed between −x² and x², the oscillating graph has no choice: its limit at 0 is 0."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_937f643ac11562', 'les_467b75bfe24e34', 'learn', 3, 'worked_example', '{"title":"$\\lim_{x \\to 0} x^2 \\sin\\frac{1}{x}$","steps":[{"latex":"-1 \\le \\sin\\tfrac{1}{x} \\le 1","explanation":""},{"latex":"-x^2 \\le x^2 \\sin\\tfrac{1}{x} \\le x^2","explanation":"Multiply by x² ≥ 0."},{"latex":"-x^2 \\to 0,\\ x^2 \\to 0","explanation":""},{"latex":"\\lim = 0","explanation":"By the Squeeze Theorem."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_c5b17ec25e4639', 'les_467b75bfe24e34', 'learn', 4, 'worked_example', '{"title":"$\\lim_{x \\to \\infty} \\dfrac{\\sin x}{x}$","steps":[{"latex":"-\\tfrac{1}{x} \\le \\tfrac{\\sin x}{x} \\le \\tfrac{1}{x}","explanation":"For x > 0."},{"latex":"\\pm\\tfrac{1}{x} \\to 0 \\Rightarrow \\lim = 0","explanation":""}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_11e10f5aa38ca9', 'les_467b75bfe24e34', 'learn', 5, 'callout', '{"tone":"note","title":"The famous one","body":"A geometric argument with areas on the unit circle gives $\\cos x \\le \\frac{\\sin x}{x} \\le 1$ near 0, so $\\lim_{x \\to 0} \\frac{\\sin x}{x} = 1$ (in radians)."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_d963b4b94554c6', 'les_467b75bfe24e34', 'learn', 6, 'callout', '{"tone":"application","title":"Where this shows up","body":"The limit $\\frac{\\sin x}{x} \\to 1$ is why $\\sin x \\approx x$ for small angles, the approximation behind the simple-pendulum formula in physics."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_97992df48bc350', 'les_467b75bfe24e34', 1, 'practice', 'numeric', 1, '$2 - x^2 \le f(x) \le 2 + x^2$ for all $x$. Find $\lim_{x \to 0} f(x)$.', '{"answer":2}', '[]', 'Both bounds approach 2.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_095f404b26f981', 'les_467b75bfe24e34', 2, 'practice', 'numeric', 2, 'Find $\lim_{x \to 0} \dfrac{\sin 2x}{\sin 3x}$ as a decimal to three places.', '{"answer":0.667,"tolerance":0.001}', '["Write it as $\\frac{2}{3} \\cdot \\frac{\\sin 2x}{2x} \\cdot \\frac{3x}{\\sin 3x}$."]', '$\frac{2}{3} \approx 0.667$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_937f643ac11562', 'les_467b75bfe24e34', 3, 'practice', 'numeric', 2, 'Find $\lim_{x \to 0} x \cos\frac{1}{x}$.', '{"answer":0}', '[]', '$-|x| \le x\cos\frac{1}{x} \le |x|$, and both bounds go to 0.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_c5b17ec25e4639', 'les_467b75bfe24e34', 4, 'review', 'multiple_choice', 3, 'Why can''t you find $\lim_{x \to 0} \sin\frac{1}{x}$ with the Squeeze Theorem using bounds −1 and 1?', '{"choices":["The bounds have different limits","sin is not continuous","The bounds aren''t functions","It''s at infinity"],"answer":0}', '[]', '−1 and 1 don''t share a limit, so nothing is forced; in fact this limit doesn''t exist.');
INSERT OR IGNORE INTO concepts (id, subject_id, slug, name, description) VALUES ('cpt_9523ccbcc4c521', 'subj_math', 'limits', 'Limits', 'The value a function''s outputs approach as the input approaches a given value.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_467b75bfe24e34', (SELECT id FROM concepts WHERE slug = 'limits'));
INSERT OR IGNORE INTO lesson_formulas (lesson_id, formula_id, position) VALUES ('les_467b75bfe24e34', (SELECT id FROM formulas WHERE slug = 'special-trig-limits'), 1);

-- Lesson: straight-line-motion
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_93817e0461c3e6', 'straight-line-motion', 'Straight-line motion: connecting position, velocity and acceleration', 'Use derivatives of position to find velocity and acceleration, decide when a particle moves left or right, is at rest, or is speeding up or slowing down.', 30, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_46cf73316958c4', 'les_93817e0461c3e6', 1, 'Compute v(t) = s′(t) and a(t) = v′(t) = s″(t).');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_b6e15cad1512df', 'les_93817e0461c3e6', 2, 'Determine direction of motion and when the particle is at rest.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_a0ede05626af23', 'les_93817e0461c3e6', 3, 'Decide whether the particle is speeding up (v and a same sign) or slowing down.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_46cf73316958c4', 'les_93817e0461c3e6', 'learn', 1, 'definition', '{"term":"Motion along a line","body":"Position $s(t)$; velocity $v(t) = s''(t)$ (sign gives direction); speed $|v(t)|$; acceleration $a(t) = v''(t)$. The particle is speeding up when $v$ and $a$ have the same sign, and slowing down when their signs differ."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_b6e15cad1512df', 'les_93817e0461c3e6', 'learn', 2, 'worked_example', '{"title":"$s(t) = t^3 - 6t^2 + 9t$ meters, $t \\ge 0$","steps":[{"latex":"v(t) = 3t^2 - 12t + 9 = 3(t - 1)(t - 3)","explanation":""},{"latex":"\\text{at rest at } t = 1, 3;\\ \\text{moving left on } (1, 3)","explanation":"v < 0 there."},{"latex":"a(t) = 6t - 12","explanation":"a < 0 for t < 2, a > 0 for t > 2."},{"latex":"\\text{speeding up on } (1, 2) \\text{ and } (3, \\infty)","explanation":"Where v and a share a sign."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_a0ede05626af23', 'les_93817e0461c3e6', 'learn', 3, 'worked_example', '{"title":"Total distance traveled on $[0, 3]$","steps":[{"latex":"s(0) = 0,\\ s(1) = 4,\\ s(3) = 0","explanation":"Split at the turn (t = 1)."},{"latex":"|4 - 0| + |0 - 4| = 8 \\text{ m}","explanation":"Displacement is 0, but distance is 8."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_95f9f6981d3faa', 'les_93817e0461c3e6', 'learn', 4, 'callout', '{"tone":"warning","title":"Speeding up isn''t ''a > 0''","body":"A car moving left ($v < 0$) with $a < 0$ is speeding up. Compare signs of $v$ and $a$."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_c6b20a09bb8fa7', 'les_93817e0461c3e6', 'learn', 5, 'callout', '{"tone":"application","title":"Where this shows up","body":"Elevator controllers, robot arms and self-driving cars all track position, velocity and acceleration as derivatives of one another."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_46cf73316958c4', 'les_93817e0461c3e6', 1, 'practice', 'numeric', 1, 'For $s(t) = t^3 - 6t^2 + 9t$, find the velocity at $t = 2$, in m/s.', '{"answer":-3,"unit":"m/s"}', '[]', '$12 - 24 + 9 = -3$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_b6e15cad1512df', 'les_93817e0461c3e6', 2, 'practice', 'numeric', 1, 'What is the speed at $t = 2$?', '{"answer":3,"unit":"m/s"}', '[]', '$|{-3}| = 3$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_a0ede05626af23', 'les_93817e0461c3e6', 3, 'practice', 'multiple_choice', 2, 'At $t = 2.5$, is the particle speeding up or slowing down?', '{"choices":["Speeding up","Slowing down","At rest","Can''t tell"],"answer":1}', '["$v(2.5) < 0$, $a(2.5) = 3 > 0$."]', 'Opposite signs: slowing down.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_95f9f6981d3faa', 'les_93817e0461c3e6', 4, 'review', 'numeric', 3, 'A ball''s height is $h(t) = -16t^2 + 48t$ feet. Find its acceleration in ft/s².', '{"answer":-32,"unit":"ft/s²"}', '[]', '$h'''' = -32$.');
INSERT OR IGNORE INTO concepts (id, subject_id, slug, name, description) VALUES ('cpt_36377b1d43a313', 'subj_math', 'derivatives', 'Derivatives', 'The instantaneous rate of change of a function; the slope of its tangent line.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_93817e0461c3e6', (SELECT id FROM concepts WHERE slug = 'derivatives'));

-- Lesson: trig-derivatives-tan-sec
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_f3414f35e2d577', 'trig-derivatives-tan-sec', 'Derivatives of tangent, cotangent, secant and cosecant', 'Derive the derivatives of tan x, cot x, sec x and csc x with the Quotient Rule, and use them with the other derivative rules.', 25, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_70cb97b65f1d7c', 'les_f3414f35e2d577', 1, 'Derive (tan x)′ = sec² x and (sec x)′ = sec x tan x from sine and cosine.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_80ca340c72010a', 'les_f3414f35e2d577', 2, 'Use all six trigonometric derivatives.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_7ae7eefe58e28b', 'les_f3414f35e2d577', 3, 'Combine them with the product and quotient rules.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_70cb97b65f1d7c', 'les_f3414f35e2d577', 'learn', 1, 'worked_example', '{"title":"$\\frac{d}{dx}\\tan x = \\frac{d}{dx}\\dfrac{\\sin x}{\\cos x}$","steps":[{"latex":"\\frac{\\cos x \\cos x - \\sin x(-\\sin x)}{\\cos^2 x}","explanation":""},{"latex":"= \\frac{1}{\\cos^2 x} = \\sec^2 x","explanation":"Pythagorean identity."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_80ca340c72010a', 'les_f3414f35e2d577', 'learn', 2, 'worked_example', '{"title":"$\\frac{d}{dx}\\sec x = \\frac{d}{dx}(\\cos x)^{-1}$","steps":[{"latex":"\\frac{0 \\cdot \\cos x - 1 \\cdot (-\\sin x)}{\\cos^2 x}","explanation":"Quotient Rule with numerator 1."},{"latex":"= \\frac{1}{\\cos x} \\cdot \\frac{\\sin x}{\\cos x} = \\sec x \\tan x","explanation":""}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_7ae7eefe58e28b', 'les_f3414f35e2d577', 'learn', 3, 'definition', '{"term":"All six","body":"$(\\tan x)'' = \\sec^2 x$, $(\\cot x)'' = -\\csc^2 x$, $(\\sec x)'' = \\sec x \\tan x$, $(\\csc x)'' = -\\csc x \\cot x$. The \"co-\" functions get a minus sign."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_715f0649494f18', 'les_f3414f35e2d577', 'learn', 4, 'callout', '{"tone":"application","title":"Where this shows up","body":"If a camera tracks a car moving along a road, the car''s position is often $d\\tan\\theta$, and the tracking speed involves $\\sec^2\\theta$."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_70cb97b65f1d7c', 'les_f3414f35e2d577', 1, 'practice', 'numeric', 1, 'Find the derivative of $\tan x$ at $x = \frac{\pi}{4}$.', '{"answer":2}', '[]', '$\sec^2\frac{\pi}{4} = (\sqrt{2})^2 = 2$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_80ca340c72010a', 'les_f3414f35e2d577', 2, 'practice', 'numeric', 1, 'Find the derivative of $\sec x$ at $x = 0$.', '{"answer":0}', '[]', '$\sec 0 \tan 0 = 0$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_7ae7eefe58e28b', 'les_f3414f35e2d577', 3, 'practice', 'multiple_choice', 2, '$\frac{d}{dx}\cot x$ is…', '{"choices":["$\\csc^2 x$","$-\\csc^2 x$","$-\\csc x\\cot x$","$\\sec^2 x$"],"answer":1}', '[]', 'Minus sign for the co-function.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_715f0649494f18', 'les_f3414f35e2d577', 4, 'review', 'numeric', 3, 'Find $\frac{d}{dx}[x\tan x]$ at $x = 0$.', '{"answer":0}', '[]', '$\tan x + x\sec^2 x = 0$ at 0.');
